((window.CARDS_BY_LANG = window.CARDS_BY_LANG || {}).el = window.CARDS_BY_LANG.el || {}).country = [{"name":"Ρωσία","emoji":"🇷🇺","meta":["Ευρώπη και Ασία","Μόσχα","περίπου 146 εκατ."],"description":"Η μεγαλύτερη χώρα του κόσμου σε έκταση, που απλώνεται σε έντεκα ζώνες ώρας, από τη Βαλτική μέχρι τον Ειρηνικό. Εδώ βρίσκεται η λίμνη Βαϊκάλη, η βαθύτερη του πλανήτη, μαζί με την απέραντη τάιγκα και την τούνδρα της Σιβηρίας.","fact":"Από τη Ρωσία περνά ο Υπερσιβηρικός, η μεγαλύτερη σε μήκος σιδηροδρομική γραμμή στον κόσμο.","wiki_en":"Russia"},{"name":"Ηνωμένες Πολιτείες","emoji":"🇺🇸","meta":["Βόρεια Αμερική","Ουάσινγκτον","περίπου 335 εκατ."],"description":"Πενήντα πολιτείες με εντελώς διαφορετικό κλίμα και τρόπο ζωής: από τους ουρανοξύστες της Νέας Υόρκης και τα φαράγγια της Αριζόνα μέχρι τα στούντιο του Λος Άντζελες. Εδώ γεννήθηκαν η τζαζ, τα μπλουζ και το ροκ εν ρολ.","fact":"Το Άγαλμα της Ελευθερίας στη Νέα Υόρκη ήταν δώρο της Γαλλίας στις Ηνωμένες Πολιτείες στα τέλη του 19ου αιώνα.","wiki_en":"United States"},{"name":"Κίνα","emoji":"🇨🇳","meta":["Ασία","Πεκίνο","περίπου 1,41 δισ."],"description":"Ένας από τους αρχαιότερους πολιτισμούς του κόσμου, που χάρισε στην ανθρωπότητα το χαρτί, την πυρίτιδα και το μετάξι. Το Σινικό Τείχος απλώνεται για χιλιάδες χιλιόμετρα, ενώ μεγαλουπόλεις όπως η Σανγκάη συνυπάρχουν με την αιωνόβια τελετή του τσαγιού.","fact":"Η Κίνα ήταν η πολυπληθέστερη χώρα του κόσμου σχεδόν σε όλη τη γραπτή ιστορία, ώσπου την ξεπέρασε πρόσφατα η Ινδία.","wiki_en":"China"},{"name":"Ιαπωνία","emoji":"🇯🇵","meta":["Ασία","Τόκιο","περίπου 124 εκατ."],"description":"Νησιωτική χώρα όπου αρχαία ιερά του σιντοϊσμού βρίσκονται λίγα βήματα από τους δρόμους του Τόκιο με τα νέον και τα υπερταχεία σινκανσέν. Η ιαπωνική κουζίνα, από το σούσι μέχρι το ράμεν, και παραδόσεις όπως το οριγκάμι είναι γνωστές παντού.","fact":"Το όρος Φούτζι, ιερό ηφαίστειο της Ιαπωνίας, προσελκύει κάθε χρόνο εκατοντάδες χιλιάδες επισκέπτες και προσκυνητές.","wiki_en":"Japan"},{"name":"Γερμανία","emoji":"🇩🇪","meta":["Ευρώπη","Βερολίνο","περίπου 84 εκατ."],"description":"Η πατρίδα του Μπαχ, του Μπετόβεν και του Μπραμς, αλλά και αυτοκινητοβιομηχανιών όπως η BMW και η Mercedes-Benz. Στη μία άκρη της χώρας τα μεσαιωνικά κάστρα της Βαυαρίας, στην άλλη η βιομηχανική δύναμη του Ρουρ.","fact":"Το Οκτόμπερφεστ του Μονάχου είναι το μεγαλύτερο φεστιβάλ μπύρας στον κόσμο και συγκεντρώνει εκατομμύρια επισκέπτες κάθε χρόνο.","wiki_en":"Germany"},{"name":"Γαλλία","emoji":"🇫🇷","meta":["Ευρώπη","Παρίσι","περίπου 68 εκατ."],"description":"Η πατρίδα της υψηλής ραπτικής, του κρασιού και μιας από τις πιο επιδραστικές κουζίνες του κόσμου, της οποίας τα πιάτα και οι σάλτσες θεμελίωσαν την κλασική εστιατορική μαγειρική. Ο πύργος του Άιφελ και το Λούβρο υποδέχονται εκατομμύρια επισκέπτες κάθε χρόνο.","fact":"Η μπαγκέτα και η παραδοσιακή γαλλική αρτοποιία έχουν εγγραφεί στον κατάλογο άυλης πολιτιστικής κληρονομιάς της UNESCO.","wiki_en":"France"},{"name":"Ιταλία","emoji":"🇮🇹","meta":["Ευρώπη","Ρώμη","περίπου 59 εκατ."],"description":"Η κοιτίδα της Ρωμαϊκής Αυτοκρατορίας και της Αναγέννησης, όπου ο Μιχαήλ Άγγελος και ο Λεονάρντο ντα Βίντσι δημιούργησαν αριστουργήματα. Η πίτσα, τα ζυμαρικά και ο εσπρέσο ξεκίνησαν από εδώ, και η χερσόνησος-μπότα είναι γεμάτη μνημεία της UNESCO.","fact":"Μέσα στην Ιταλία βρίσκεται το Βατικανό, ένα ξεχωριστό κράτος που περιβάλλεται εξ ολοκλήρου από τη Ρώμη.","wiki_en":"Italy"},{"name":"Ισπανία","emoji":"🇪🇸","meta":["Ευρώπη","Μαδρίτη","περίπου 47 εκατ."],"description":"Χώρα του φλαμένκο, της ταυρομαχίας και της σιέστας, που χάρισε στον κόσμο την παέγια και τα τάπας. Η αρχιτεκτονική του Αντόνι Γκαουδί στη Βαρκελώνη και η μαυριτανική κληρονομιά της Ανδαλουσίας την κάνουν έναν από τους πιο επισκέψιμους προορισμούς της Ευρώπης.","fact":"Η Ισπανία είναι η δεύτερη μεγαλύτερη σε έκταση χώρα της Ευρωπαϊκής Ένωσης, μετά τη Γαλλία.","wiki_en":"Spain"},{"name":"Ηνωμένο Βασίλειο","emoji":"🇬🇧","meta":["Ευρώπη","Λονδίνο","περίπου 68 εκατ."],"description":"Νησιωτικό βασίλειο που χάρισε στον κόσμο το ποδόσφαιρο, τους The Beatles και το απογευματινό τσάι. Το Μπιγκ Μπεν στο Λονδίνο, τα ορεινά της Σκωτίας και τα κάστρα της Ουαλίας δείχνουν την ποικιλία των τεσσάρων ιστορικών του μερών.","fact":"Το Ηνωμένο Βασίλειο αποτελείται από τέσσερα μέρη: την Αγγλία, τη Σκωτία, την Ουαλία και τη Βόρεια Ιρλανδία.","wiki_en":"United Kingdom"},{"name":"Πορτογαλία","emoji":"🇵🇹","meta":["Ευρώπη","Λισαβόνα","περίπου 10 εκατ."],"description":"Χώρα θαλασσοπόρων της εποχής των ανακαλύψεων, με καραβέλες που έφτασαν στην Ινδία και στη Βραζιλία. Το φάντο, τα μελαγχολικά τραγούδια με κιθάρα, και το πορτό από την κοιλάδα του Ντούρο έγιναν η ταυτότητά της.","fact":"Η Πορτογαλία θεωρείται μία από τις παλαιότερες χώρες της Ευρώπης, με σύνορα σχεδόν αμετάβλητα για αιώνες.","wiki_en":"Portugal"},{"name":"Ολλανδία","emoji":"🇳🇱","meta":["Ευρώπη","Άμστερνταμ","περίπου 18 εκατ."],"description":"Χώρα με κανάλια, τουλίπες και ανεμόμυλους, που κέρδισε μεγάλο μέρος του εδάφους της από τη θάλασσα με φράγματα και αποξηράνσεις. Το Άμστερνταμ φημίζεται για την κουλτούρα του ποδηλάτου και για τους πίνακες του Ρέμπραντ και του Βαν Γκογκ.","fact":"Περίπου το ένα τέταρτο της Ολλανδίας βρίσκεται κάτω από την επιφάνεια της θάλασσας και σχεδόν το μισό λιγότερο από ένα μέτρο πάνω από αυτήν.","wiki_en":"Netherlands"},{"name":"Βέλγιο","emoji":"🇧🇪","meta":["Ευρώπη","Βρυξέλλες","περίπου 12 εκατ."],"description":"Μικρή χώρα με φήμη για τη σοκολάτα, τις βάφλες και εκατοντάδες ποικιλίες μπύρας, αλλά και για τα κόμικς του Τεντέν και των Στρουμφ. Στις Βρυξέλλες βρίσκονται οι έδρες της Ευρωπαϊκής Ένωσης και του ΝΑΤΟ.","fact":"Οι Βέλγοι θεωρούν τη χώρα τους πατρίδα των πατατών τηγανητών, παρότι σε πολλές γλώσσες τις λένε ακόμη «γαλλικές».","wiki_en":"Belgium"},{"name":"Ελβετία","emoji":"🇨🇭","meta":["Ευρώπη","Βέρνη","περίπου 9 εκατ."],"description":"Ορεινή χώρα φημισμένη για τα ρολόγια ακριβείας, τη σοκολάτα και το τυρί με τις τρύπες. Οι αλπικές πλαγιές τραβούν σκιέρ και ορειβάτες, ενώ η ουδετερότητα της Ελβετίας κρατά πάνω από δύο αιώνες.","fact":"Η Ελβετία έχει τέσσερις επίσημες γλώσσες: τα γερμανικά, τα γαλλικά, τα ιταλικά και τα ρομανσικά.","wiki_en":"Switzerland"},{"name":"Αυστρία","emoji":"🇦🇹","meta":["Ευρώπη","Βιέννη","περίπου 9 εκατ."],"description":"Αλπική χώρα με εξαιρετική μουσική κληρονομιά: εδώ έγραψαν ο Μότσαρτ, ο Χάυδν και ο Στράους. Τα βιεννέζικα καφέ, το παλάτι Σένμπρουν και τα χιονισμένα θέρετρα του Τιρόλο δίνουν τον χαρακτήρα της.","fact":"Οι χοροί της Βιέννης και η παράδοση του βαλς αποτελούν αναπόσπαστο κομμάτι της αυστριακής πολιτιστικής ταυτότητας.","wiki_en":"Austria"},{"name":"Σουηδία","emoji":"🇸🇪","meta":["Ευρώπη","Στοκχόλμη","περίπου 10 εκατ."],"description":"Σκανδιναβική χώρα με χιλιάδες λίμνες και νησιά, που χάρισε στον κόσμο τους ABBA, τα έπιπλα IKEA και το «φίκα», τη συνήθεια της παύσης για καφέ και κάτι γλυκό. Η Στοκχόλμη είναι χτισμένη πάνω σε δεκατέσσερα νησιά.","fact":"Τη ζώνη ασφαλείας τριών σημείων, που έγινε στάνταρ σε όλα τα αυτοκίνητα του κόσμου, τη σχεδίασαν μηχανικοί της σουηδικής Volvo.","wiki_en":"Sweden"},{"name":"Νορβηγία","emoji":"🇳🇴","meta":["Ευρώπη","Όσλο","περίπου 5,5 εκατ."],"description":"Η χώρα των φιόρδ, των στενών θαλάσσιων κόλπων ανάμεσα σε ψηλούς βράχους, και η κοιτίδα του σκι και των θρύλων των Βίκινγκ. Πάνω από τον Αρκτικό Κύκλο το βόρειο σέλας φωτίζει τον χειμωνιάτικο ουρανό.","fact":"Οι Νορβηγοί ήταν από τους πρώτους που χρησιμοποίησαν μαζικά τα πέδιλα για μετακίνηση, και η λέξη «ski» είναι νορβηγική.","wiki_en":"Norway"},{"name":"Φινλανδία","emoji":"🇫🇮","meta":["Ευρώπη","Ελσίνκι","περίπου 5,6 εκατ."],"description":"Χώρα με χιλιάδες λίμνες και πυκνά δάση, όπου η σάουνα δεν είναι πολυτέλεια αλλά κομμάτι της καθημερινότητας σχεδόν κάθε οικογένειας. Από εδώ ξεκίνησαν η Nokia και οι Μούμιν, και η χώρα βρίσκεται σταθερά στην κορυφή των πιο ευτυχισμένων λαών.","fact":"Στη Φινλανδία υπάρχουν περισσότερες σάουνες από αυτοκίνητα: βρίσκεις μία σχεδόν σε κάθε σπίτι και διαμέρισμα.","wiki_en":"Finland"},{"name":"Δανία","emoji":"🇩🇰","meta":["Ευρώπη","Κοπεγχάγη","περίπου 6 εκατ."],"description":"Σκανδιναβικό βασίλειο που χάρισε στον κόσμο τα τουβλάκια LEGO και τα παραμύθια του Χανς Κρίστιαν Άντερσεν. Οι Δανοί ήταν από τους πρώτους λαούς που έκαναν το ποδήλατο βασικό μέσο μεταφοράς στην πόλη.","fact":"Η Δανία είναι μία από τις παλαιότερες μοναρχίες του κόσμου, με αδιάκοπη σειρά μοναρχών.","wiki_en":"Denmark"},{"name":"Ισλανδία","emoji":"🇮🇸","meta":["Ευρώπη","Ρέικιαβικ","περίπου 380 χιλ."],"description":"Νησί ηφαιστείων, θερμοπιδάκων και παγετώνων, όπου οι θερμές πηγές γειτονεύουν με άγριες εκτάσεις λάβας. Παρά το όνομά της, η Ισλανδία φημίζεται λιγότερο για τον πάγο και περισσότερο για τη γεωθερμία που θερμαίνει σχεδόν όλα τα σπίτια.","fact":"Η Ισλανδία σχεδόν δεν έχει δάση, και ο θρύλος για τον κρυμμένο λαό των ξωτικών που ζουν στα βράχια είναι ακόμη ζωντανός.","wiki_en":"Iceland"},{"name":"Ιρλανδία","emoji":"🇮🇪","meta":["Ευρώπη","Δουβλίνο","περίπου 5,3 εκατ."],"description":"Το σμαραγδένιο νησί, πράσινο σε εκατό αποχρώσεις, φημισμένο για τις παμπ του, την παραδοσιακή μουσική και την αγάπη του για τις ιστορίες. Από εδώ ξεκίνησαν η μπύρα Guinness και η γιορτή του Αγίου Πατρικίου, που γιορτάζεται σε όλο τον κόσμο.","fact":"Το τριφύλλι είναι εθνικό σύμβολο της Ιρλανδίας και συνδέεται με τον θρύλο του Αγίου Πατρικίου.","wiki_en":"Republic of Ireland"},{"name":"Πολωνία","emoji":"🇵🇱","meta":["Ευρώπη","Βαρσοβία","περίπου 38 εκατ."],"description":"Χώρα με πλούσια ιστορία και μεσαιωνικό κέντρο στη Βαρσοβία, που ξαναχτίστηκε μετά τον πόλεμο και μπήκε στον κατάλογο της UNESCO. Εδώ γεννήθηκαν ο Σοπέν και η Μαρία Σκλοντόφσκα-Κιουρί, και τα πιερόγκι είναι γνωστά πολύ έξω από τα σύνορα.","fact":"Ο ναός της Παναγίας στην Κρακοβία φημίζεται για τον τρομπετίστα που παίζει κάθε ώρα μια μελωδία, η οποία κόβεται απότομα στη μέση.","wiki_en":"Poland"},{"name":"Τσεχία","emoji":"🇨🇿","meta":["Ευρώπη","Πράγα","περίπου 10,9 εκατ."],"description":"Χώρα μεσαιωνικών κάστρων και ζυθοποιείων, όπου πίνουν περισσότερη μπύρα κατά κεφαλήν από οπουδήποτε αλλού στον κόσμο. Η Πράγα, με τη γέφυρα του Καρόλου και το κάστρο πάνω από το ποτάμι, θεωρείται μία από τις ομορφότερες πόλεις της Ευρώπης.","fact":"Η λέξη «ρομπότ» είναι τσεχική: τη χρησιμοποίησε πρώτος ο συγγραφέας Κάρελ Τσάπεκ σε θεατρικό του το 1920.","wiki_en":"Czech Republic"},{"name":"Ουγγαρία","emoji":"🇭🇺","meta":["Ευρώπη","Βουδαπέστη","περίπου 9,6 εκατ."],"description":"Χώρα πάνω στον Δούναβη, φημισμένη για τα ιαματικά λουτρά της Βουδαπέστης και για το γκούλας με άφθονη πάπρικα. Τα ουγγρικά δεν μοιάζουν με καμία γειτονική γλώσσα, και ο ξέφρενος τσάρντας και η μουσική του Φραντς Λιστ είναι εθνική υπόθεση.","fact":"Η Βουδαπέστη προέκυψε στα τέλη του 19ου αιώνα από την ένωση τριών πόλεων: της Βούδας, της Πέστης και της Όμπουδα.","wiki_en":"Hungary"},{"name":"Ελλάδα","emoji":"🇬🇷","meta":["Ευρώπη","Αθήνα","περίπου 10,4 εκατ."],"description":"Η κοιτίδα της ευρωπαϊκής φιλοσοφίας, του θεάτρου και των Ολυμπιακών Αγώνων, που έδωσε στον κόσμο τη δημοκρατία ως πολίτευμα. Τα κάτασπρα σπίτια της Σαντορίνης και τα μνημεία της Ακρόπολης φέρνουν κάθε χρόνο εκατομμύρια επισκέπτες.","fact":"Η Ελλάδα έχει αρκετές χιλιάδες νησιά, όμως μόνο περίπου διακόσια από αυτά κατοικούνται μόνιμα.","wiki_en":"Greece"},{"name":"Τουρκία","emoji":"🇹🇷","meta":["Ευρώπη και Ασία","Άγκυρα","περίπου 85 εκατ."],"description":"Χώρα απλωμένη σε δύο ηπείρους, την Ευρώπη και την Ασία, που χωρίζονται από τον Βόσπορο στην Κωνσταντινούπολη. Εδώ συναντιούνται η βυζαντινή και η οθωμανική κληρονομιά, τα ατέλειωτα τσάι και μια γενναιόδωρη αντίληψη της φιλοξενίας.","fact":"Η Τουρκία παράγει το μεγαλύτερο μέρος των φουντουκιών του κόσμου, που καταλήγουν σε σοκολατοβιομηχανίες παντού.","wiki_en":"Turkey"},{"name":"Κροατία","emoji":"🇭🇷","meta":["Ευρώπη","Ζάγκρεμπ","περίπου 3,9 εκατ."],"description":"Δαντελωτή αδριατική ακτή με χίλια νησιά και η παλιά πόλη της Ντουμπρόβνικ πίσω από τα επιβλητικά της τείχη. Η Κροατία θεωρείται η πατρίδα της γραβάτας, που πήρε το όνομά της από τη γαλλική λέξη για τους Κροάτες.","fact":"Το εθνικό πάρκο των λιμνών Πλίτβιτσε φημίζεται για τους καταρράκτες που ενώνουν δεκαέξι γαλαζοπράσινες λίμνες.","wiki_en":"Croatia"},{"name":"Σερβία","emoji":"🇷🇸","meta":["Ευρώπη","Βελιγράδι","περίπου 6,6 εκατ."],"description":"Βαλκανική χώρα στη συμβολή του Δούναβη με τον Σάβο, γνωστή για τα θορυβώδη φεστιβάλ χάλκινων πνευστών και για το κάστρο Καλεμέγκνταν στο Βελιγράδι. Η σερβική κουζίνα στηρίζεται στη σχάρα και σε τουρκικές και αυστροουγγρικές επιρροές.","fact":"Ο Νόβακ Τζόκοβιτς, ένας από τους μεγαλύτερους τενίστες όλων των εποχών, γεννήθηκε στο Βελιγράδι.","wiki_en":"Serbia"},{"name":"Μαυροβούνιο","emoji":"🇲🇪","meta":["Ευρώπη","Ποντγκόριτσα","περίπου 620 χιλ."],"description":"Μικρή βαλκανική χώρα όπου τα βουνά κατεβαίνουν σχεδόν κατακόρυφα στην Αδριατική. Το μεσαιωνικό Κότορ, περιτειχισμένο στο βάθος ενός στενού κόλπου, είναι η πιο αναγνωρίσιμη εικόνα της χώρας.","fact":"Το όνομα της χώρας σημαίνει «μαύρο βουνό», από μια οροσειρά καλυμμένη με σκούρα δάση.","wiki_en":"Montenegro"},{"name":"Βουλγαρία","emoji":"🇧🇬","meta":["Ευρώπη","Σόφια","περίπου 6,4 εκατ."],"description":"Βαλκανική χώρα με τις τριανταφυλλιές της κοιλάδας του Καζανλάκ, που δίνουν ροδέλαιο στην αρωματοποιία όλου του κόσμου. Το βουλγαρικό γιαούρτι και η οινοποιία της φτάνουν πίσω στους αρχαίους Θράκες.","fact":"Το κυριλλικό αλφάβητο, που χρησιμοποιείται στη Ρωσία και σε άλλες χώρες, δημιουργήθηκε και εξελίχθηκε στη μεσαιωνική Βουλγαρία.","wiki_en":"Bulgaria"},{"name":"Ρουμανία","emoji":"🇷🇴","meta":["Ευρώπη","Βουκουρέστι","περίπου 19 εκατ."],"description":"Χώρα των Καρπαθίων και της Τρανσυλβανίας, δεμένη στη φαντασία του κόσμου με τον κόμη Δράκουλα και το κάστρο Μπραν. Τα ρουμανικά κράτησαν τις λατινικές τους ρίζες, περικυκλωμένα από σλαβικές γλώσσες και τα ουγγρικά.","fact":"Το κάστρο Μπραν στην Τρανσυλβανία συνδέεται συχνά με τον θρύλο του Δράκουλα, αν και η ιστορική σχέση είναι ισχνή.","wiki_en":"Romania"},{"name":"Ουκρανία","emoji":"🇺🇦","meta":["Ευρώπη","Κίεβο","περίπου 38 εκατ."],"description":"Η μεγαλύτερη χώρα που βρίσκεται εξ ολοκλήρου στην Ευρώπη, με εύφορες στέπες μαύρης γης που τρέφουν από παλιά μεγάλο μέρος της ηπείρου. Η Λαύρα των Σπηλαίων στο Κίεβο και τα κεντημένα πουκάμισα βισιβάνκα ανήκουν σε μια κληρονομιά αιώνων.","fact":"Η UNESCO ενέγραψε την ουκρανική κουλτούρα του μπορς στον κατάλογο άυλης πολιτιστικής κληρονομιάς.","wiki_en":"Ukraine"},{"name":"Λευκορωσία","emoji":"🇧🇾","meta":["Ευρώπη","Μινσκ","περίπου 9,2 εκατ."],"description":"Χώρα με χιλιάδες λίμνες και απέραντα δάση, ανάμεσά τους το Μπελοβέζσκαγια Πούστσα, ένα από τα τελευταία παρθένα δάση της Ευρώπης, όπου ζουν βίσωνες. Το Μινσκ ξαναχτίστηκε σχεδόν από την αρχή μετά τον πόλεμο και ξεχωρίζει για τις φαρδιές λεωφόρους του.","fact":"Στο Μπελοβέζσκαγια Πούστσα ζει ένας από τους μεγαλύτερους πληθυσμούς βίσωνα στην Ευρώπη, μετά τη σχεδόν ολική εξαφάνισή του.","wiki_en":"Belarus"},{"name":"Γεωργία","emoji":"🇬🇪","meta":["Ασία","Τιφλίδα","περίπου 3,7 εκατ."],"description":"Χώρα του Καυκάσου με μία από τις αρχαιότερες παραδόσεις οινοποιίας στον κόσμο: το κρασί παλαιώνει ακόμη σε πήλινα αγγεία, τα κβέβρι. Τα ορεινά τοπία της Σβανετίας και τα χινκάλι με το χατσαπούρι την έκαναν αγαπημένη των γαστροταξιδιωτών.","fact":"Η γεωργιανή οινοποιία στα κβέβρι αναγνωρίζεται από την UNESCO ως άυλη πολιτιστική κληρονομιά.","wiki_en":"Georgia (country)"},{"name":"Αρμενία","emoji":"🇦🇲","meta":["Ασία","Ερεβάν","περίπου 3 εκατ."],"description":"Μία από τις αρχαιότερες χριστιανικές χώρες του κόσμου, με μοναστήρια άνω των χιλίων ετών να στέκουν μπροστά στο χιονισμένο Αραράτ. Το αρμενικό κονιάκ και τα γενναιόδωρα τραπέζια της φιλοξενίας είναι γνωστά πολύ πιο πέρα από τον Καύκασο.","fact":"Η Αρμενία ανακήρυξε τον χριστιανισμό επίσημη θρησκεία στις αρχές του 4ου αιώνα, από τις πρώτες χώρες στον κόσμο.","wiki_en":"Armenia"},{"name":"Αζερμπαϊτζάν","emoji":"🇦🇿","meta":["Ασία","Μπακού","περίπου 10,2 εκατ."],"description":"Χώρα της Κασπίας, όπου οι παλιοί πέτρινοι πύργοι της παλιάς πόλης του Μπακού στέκουν στη σκιά των φουτουριστικών Flame Towers. Το πετρέλαιο αντλείται εδώ από τον 19ο αιώνα, και το όνομα της πρωτεύουσας συνδέεται με τους ανέμους της Κασπίας.","fact":"Το Μπακού το λένε συχνά «πόλη των ανέμων», εξαιτίας των δυνατών και σταθερών ανέμων που έρχονται από την Κασπία.","wiki_en":"Azerbaijan"},{"name":"Καζακστάν","emoji":"🇰🇿","meta":["Ασία","Αστάνα","περίπου 20 εκατ."],"description":"Η μεγαλύτερη χώρα της Κεντρικής Ασίας, όπου η απέραντη στέπα φτάνει στις χιονισμένες κορυφογραμμές του Τιεν Σαν. Από το κοσμοδρόμιο του Μπαϊκονούρ εκτοξεύονται διαστημόπλοια, ενώ η νομαδική παράδοση της ιπποτροφίας παραμένει ζωντανή.","fact":"Το Καζακστάν είναι η μεγαλύτερη χώρα στον κόσμο χωρίς πρόσβαση στη θάλασσα.","wiki_en":"Kazakhstan"},{"name":"Ουζμπεκιστάν","emoji":"🇺🇿","meta":["Ασία","Τασκένδη","περίπου 36 εκατ."],"description":"Χώρα πάνω στον αρχαίο Δρόμο του Μεταξιού, όπου οι γαλαζοπράσινοι θόλοι των μεντρεσέδων της Σαμαρκάνδης και της Μπουχάρα κρατούν τη μνήμη των μεγάλων καραβανιών. Το ουζμπεκικό πιλάφι, μαγειρεμένο σε καζάνι, είναι σύμβολο της εθνικής κουζίνας.","fact":"Η Σαμαρκάνδη και η Μπουχάρα ήταν για αιώνες από τους σημαντικότερους σταθμούς του Δρόμου του Μεταξιού.","wiki_en":"Uzbekistan"},{"name":"Κιργιστάν","emoji":"🇰🇬","meta":["Ασία","Μπισκέκ","περίπου 7 εκατ."],"description":"Ορεινή χώρα του Τιεν Σαν, όπου η νομαδική ζωή συνεχίζεται: οι γιούρτες και τα ορεινά βοσκοτόπια τζαϊλόο είναι ακόμη μέρος της καθημερινότητας. Η λίμνη Ισίκ Κουλ, μία από τις μεγαλύτερες ορεινές λίμνες του κόσμου, δεν παγώνει ποτέ τον χειμώνα.","fact":"Το όνομα Ισίκ Κουλ σημαίνει «ζεστή λίμνη»: τα νερά της δεν παγώνουν ούτε στους πιο βαρείς παγετούς.","wiki_en":"Kyrgyzstan"},{"name":"Εσθονία","emoji":"🇪🇪","meta":["Ευρώπη","Ταλίν","περίπου 1,3 εκατ."],"description":"Βαλτική χώρα με μία από τις καλύτερα διατηρημένες μεσαιωνικές παλιές πόλεις της Ευρώπης, το Ταλίν. Η Εσθονία θεωρείται πρωτοπόρος της ψηφιακής διακυβέρνησης και από τις πρώτες χώρες που εισήγαγαν την ηλεκτρονική υπηκοότητα.","fact":"Η Εσθονία ήταν από τις πρώτες χώρες στον κόσμο που μετέφερε σχεδόν όλες τις δημόσιες υπηρεσίες της στο διαδίκτυο.","wiki_en":"Estonia"},{"name":"Λετονία","emoji":"🇱🇻","meta":["Ευρώπη","Ρίγα","περίπου 1,9 εκατ."],"description":"Βαλτική χώρα με πευκοδάση και αμμώδεις παραλίες, της οποίας η πρωτεύουσα Ρίγα έχει τη μεγαλύτερη συλλογή κτηρίων αρ νουβό στην Ευρώπη. Το θερινό ηλιοστάσιο, το Γιάνι, γιορτάζεται με τραγούδια και στεφάνια από βότανα.","fact":"Στη Λετονία παραμένει ζωντανή η παράδοση των εθνικών γιορτών τραγουδιού, όπου ενωμένες χορωδίες χιλιάδων ατόμων τραγουδούν μαζί.","wiki_en":"Latvia"},{"name":"Λιθουανία","emoji":"🇱🇹","meta":["Ευρώπη","Βίλνιους","περίπου 2,8 εκατ."],"description":"Βαλτική χώρα με τη μεγαλύτερη μεσαιωνική παλιά πόλη της Ανατολικής Ευρώπης στο Βίλνιους, και άλλοτε κέντρο του τεράστιου Μεγάλου Δουκάτου της Λιθουανίας. Η Κουρονική Λωρίδα, με τους αμμόλοφους της, μοιράζεται ανάμεσα στη Λιθουανία και τη Ρωσία.","fact":"Η Λιθουανία ήταν η τελευταία ειδωλολατρική χώρα της Ευρώπης: ασπάστηκε επίσημα τον χριστιανισμό μόλις στα τέλη του 14ου αιώνα.","wiki_en":"Lithuania"},{"name":"Κύπρος","emoji":"🇨🇾","meta":["Ευρώπη","Λευκωσία","περίπου 1,2 εκατ."],"description":"Μεσογειακό νησί που κατά τον μύθο είναι ο τόπος γέννησης της Αφροδίτης, της θεάς του έρωτα, η οποία αναδύθηκε από τον αφρό της θάλασσας στις ακτές του. Φημίζεται για τα αρχαία ψηφιδωτά, τους ελαιώνες και τα αμπέλια στις πλαγιές του Τροόδους.","fact":"Η Κύπρος είναι γνωστή για το χαλούμι, ένα τυρί που σχεδόν δεν λιώνει και γι' αυτό κρατά το σχήμα του στη σχάρα.","wiki_en":"Cyprus"},{"name":"Μάλτα","emoji":"🇲🇹","meta":["Ευρώπη","Βαλέτα","περίπου 540 χιλ."],"description":"Μικροσκοπικό αρχιπέλαγος στο κέντρο της Μεσογείου, με επιβλητικά τείχη που έχτισαν οι Ιωαννίτες ιππότες. Το μελί χρώμα του ντόπιου ασβεστόλιθου δίνει στις πόλεις της Μάλτας μια χρυσαφένια λάμψη στο ηλιοβασίλεμα.","fact":"Η Μάλτα είναι από τις πιο πυκνοκατοικημένες χώρες του κόσμου, παρά την πολύ μικρή της έκταση.","wiki_en":"Malta"},{"name":"Μονακό","emoji":"🇲🇨","meta":["Ευρώπη","Μονακό","περίπου 39 χιλ."],"description":"Μικροσκοπικό κρατίδιο στην Κυανή Ακτή, φημισμένο για το καζίνο του Μόντε Κάρλο και για τον ετήσιο αγώνα της Formula 1 μέσα στους δρόμους της πόλης. Στριμωγμένο ανάμεσα στη θάλασσα και τους λόφους, είναι το δεύτερο μικρότερο κράτος του κόσμου μετά το Βατικανό.","fact":"Η πίστα του Γκραν Πρι του Μονακό περνά από απλούς δρόμους της πόλης, μαζί με το διάσημο τούνελ κοντά στο λιμάνι.","wiki_en":"Monaco"},{"name":"Βατικανό","emoji":"🇻🇦","meta":["Ευρώπη","Βατικανό","περίπου 800 άτομα"],"description":"Το μικρότερο κράτος του κόσμου, εξ ολοκλήρου μέσα στη Ρώμη, και το πνευματικό κέντρο της Καθολικής Εκκλησίας με επικεφαλής τον Πάπα. Η βασιλική του Αγίου Πέτρου και η οροφή της Καπέλα Σιστίνα, ζωγραφισμένη από τον Μιχαήλ Άγγελο, είναι οι μεγάλοι θησαυροί του.","fact":"Το Βατικανό είναι τόσο μικρό που μπορείς να το περπατήσεις γύρω γύρω σε λιγότερο από μία ώρα.","wiki_en":"Vatican City"},{"name":"Ισραήλ","emoji":"🇮🇱","meta":["Ασία","Ιερουσαλήμ","περίπου 9,8 εκατ."],"description":"Χώρα στην ανατολική Μεσόγειο, ιερή για τρεις παγκόσμιες θρησκείες χάρη στην Ιερουσαλήμ και τα αρχαία της μνημεία. Το Τελ Αβίβ είναι γνωστό ως ζωντανό κέντρο τεχνολογίας και πολιτισμού, με παραλίες πάνω στην ακτή.","fact":"Η Νεκρά Θάλασσα, στα σύνορα του Ισραήλ, είναι τόσο αλμυρή που ο κολυμβητής επιπλέει σχεδόν χωρίς προσπάθεια.","wiki_en":"Israel"},{"name":"Ηνωμένα Αραβικά Εμιράτα","emoji":"🇦🇪","meta":["Ασία","Άμπου Ντάμπι","περίπου 10 εκατ."],"description":"Ένωση επτά εμιράτων στον Περσικό Κόλπο, που μετέτρεψε την έρημο σε φουτουριστικές μεγαλουπόλεις όπως το Ντουμπάι, με ουρανοξύστες και τεχνητά νησιά. Πριν από λίγες δεκαετίες ήταν οικισμοί ψαράδων και δυτών μαργαριταριών, σήμερα κόμβος εμπορίου και τουρισμού.","fact":"Στο Ντουμπάι βρίσκεται ο Μπουρτζ Χαλίφα, το ψηλότερο κτήριο του κόσμου, που ξεπερνά τα οκτακόσια μέτρα.","wiki_en":"United Arab Emirates"},{"name":"Σαουδική Αραβία","emoji":"🇸🇦","meta":["Ασία","Ριάντ","περίπου 36 εκατ."],"description":"Το μεγαλύτερο κράτος της Αραβικής Χερσονήσου, στο έδαφος του οποίου βρίσκονται η Μέκκα και η Μεδίνα, οι ιερότερες πόλεις του Ισλάμ. Το ετήσιο προσκύνημα του χατζ συγκεντρώνει εδώ εκατομμύρια πιστούς από όλον τον κόσμο.","fact":"Η Σαουδική Αραβία καλύπτει το μεγαλύτερο μέρος της Ρουμπ αλ Χάλι, μιας από τις μεγαλύτερες αμμώδεις ερήμους του πλανήτη.","wiki_en":"Saudi Arabia"},{"name":"Κατάρ","emoji":"🇶🇦","meta":["Ασία","Ντόχα","περίπου 2,7 εκατ."],"description":"Μικρή χερσόνησος στον Περσικό Κόλπο, που πλούτισε από το φυσικό αέριο και γέμισε την πρωτεύουσά της, τη Ντόχα, με πύργους πάνω από την έρημο. Το 2022 φιλοξένησε το πρώτο Παγκόσμιο Κύπελλο ποδοσφαίρου που έγινε ποτέ στη Μέση Ανατολή.","fact":"Το Κατάρ ήταν η πρώτη χώρα της Μέσης Ανατολής που φιλοξένησε Παγκόσμιο Κύπελλο ποδοσφαίρου.","wiki_en":"Qatar"},{"name":"Ιράν","emoji":"🇮🇷","meta":["Ασία","Τεχεράνη","περίπου 89 εκατ."],"description":"Κληρονόμος της αρχαίας Περσικής Αυτοκρατορίας, με τα ερείπια της Περσέπολης και τα πολυτελή τζαμιά του Ισφαχάν, στρωμένα με γαλαζοπράσινα πλακίδια. Η περσική ποίηση του Χαφίζ και του Ομάρ Καγιάμ και η τελετουργία του τσαγιού ζουν στην καθημερινότητα.","fact":"Τα χειροποίητα περσικά χαλιά από το Ιράν θεωρούνται εδώ και αιώνες από τα πιο πολύτιμα στον κόσμο.","wiki_en":"Iran"},{"name":"Ιορδανία","emoji":"🇯🇴","meta":["Ασία","Αμμάν","περίπου 11 εκατ."],"description":"Χώρα της Μέσης Ανατολής, όπου η αρχαία Πέτρα είναι λαξευμένη μέσα σε ροδόχρωμους βράχους, κατάλοιπο του χαμένου ναβαταϊκού πολιτισμού. Τα τοπία της ερήμου Γουάντι Ραμ, που θυμίζουν Άρη, είναι γνωστά από δεκάδες ταινίες επιστημονικής φαντασίας.","fact":"Η Πέτρα σκαλίστηκε στα βράχια από τους Ναβαταίους πάνω από δύο χιλιάδες χρόνια πριν και έμεινε για καιρό ξεχασμένη.","wiki_en":"Jordan"},{"name":"Αίγυπτος","emoji":"🇪🇬","meta":["Αφρική","Κάιρο","περίπου 112 εκατ."],"description":"Η χώρα των πυραμίδων της Γκίζας και της Σφίγγας, όπου ένας από τους αρχαιότερους πολιτισμούς αναπτύχθηκε για χιλιετίες στις εύφορες όχθες του Νείλου. Τα ιερογλυφικά, οι φαραώ και οι θησαυροί του Τουταγχαμών τραβούν ακόμη ταξιδιώτες από παντού.","fact":"Η Μεγάλη Πυραμίδα της Γκίζας παρέμεινε για σχεδόν τέσσερις χιλιάδες χρόνια το ψηλότερο κατασκεύασμα ανθρώπινου χεριού.","wiki_en":"Egypt"},{"name":"Μαρόκο","emoji":"🇲🇦","meta":["Αφρική","Ραμπάτ","περίπου 37 εκατ."],"description":"Χώρα της Βόρειας Αφρικής, όπου οι λαβύρινθοι των παλιών μεντίνων του Μαρακές και της Φεζ δίνουν τη θέση τους στις άμμους της Σαχάρα και στις πλαγιές του Άτλαντα. Το τσάι με μέντα, το τατζίν και τα πολύχρωμα χαλιά είναι κομμάτι μιας πλούσιας χειροτεχνίας.","fact":"Το Σεφσαουέν, η γαλάζια πόλη στα βουνά του Μαρόκου, είναι βαμμένο σχεδόν ολόκληρο σε αποχρώσεις του μπλε.","wiki_en":"Morocco"},{"name":"Τυνησία","emoji":"🇹🇳","meta":["Αφρική","Τύνιδα","περίπου 12 εκατ."],"description":"Μικρή χώρα της Βόρειας Αφρικής με τα ερείπια της αρχαίας Καρχηδόνας, που κάποτε πολέμησε με τη Ρώμη για την κυριαρχία στη Μεσόγειο. Ασπρογάλαζα χωριά όπως το Σίντι Μπου Σαΐντ κοιτάζουν από τον γκρεμό τα γαλαζοπράσινα νερά.","fact":"Οι σκηνές στην έρημο για τη σάγκα του «Πολέμου των Άστρων» γυρίστηκαν στη νότια Τυνησία.","wiki_en":"Tunisia"},{"name":"Νότια Αφρική","emoji":"🇿🇦","meta":["Αφρική","Πρετόρια","περίπου 60 εκατ."],"description":"Χώρα στο νότιο άκρο της Αφρικής, όπου στο ακρωτήριο Αγκούλιας συναντιούνται ο Ατλαντικός με τον Ινδικό Ωκεανό. Τα εθνικά πάρκα με σαβάνες γεμάτες λιοντάρια και ελέφαντες και τα αμπέλια κοντά στο Κέιπ Τάουν δείχνουν μια σπάνια φυσική ποικιλία.","fact":"Η Νότια Αφρική έχει τρεις πρωτεύουσες: τη διοικητική Πρετόρια, τη νομοθετική Κέιπ Τάουν και τη δικαστική Μπλουμφοντέιν.","wiki_en":"South Africa"},{"name":"Κένυα","emoji":"🇰🇪","meta":["Αφρική","Ναϊρόμπι","περίπου 55 εκατ."],"description":"Χώρα της Ανατολικής Αφρικής, φημισμένη για τη σαβάνα του Μασάι Μάρα, την οποία διασχίζει κάθε χρόνο η Μεγάλη Μετανάστευση εκατομμυρίων γκνου και ζέβρων. Οι Κενυάτες δρομείς μεγάλων αποστάσεων κυριαρχούν στους μαραθωνίους εδώ και δεκαετίες.","fact":"Οι Κενυάτες αθλητές από την περιοχή του Ρίφτ Βάλεϊ θεωρούνται από τους δυνατότερους μαραθωνοδρόμους στον κόσμο.","wiki_en":"Kenya"},{"name":"Τανζανία","emoji":"🇹🇿","meta":["Αφρική","Ντοντόμα","περίπου 65 εκατ."],"description":"Χώρα της Ανατολικής Αφρικής, όπου βρίσκεται το Κιλιμάντζαρο, το ψηλότερο βουνό της ηπείρου, με παγετώδη κορυφή σχεδόν πάνω στον Ισημερινό. Το πάρκο Σερενγκέτι και το νησί της Ζανζιβάρης με τα μπαχαρικά του τραβούν ταξιδιώτες από παντού.","fact":"Το Κιλιμάντζαρο είναι το ψηλότερο μεμονωμένο βουνό του κόσμου, καθώς δεν ανήκει σε καμία οροσειρά.","wiki_en":"Tanzania"},{"name":"Αιθιοπία","emoji":"🇪🇹","meta":["Αφρική","Αντίς Αμπέμπα","περίπου 126 εκατ."],"description":"Μία από τις αρχαιότερες ανεξάρτητες χώρες της Αφρικής, που δεν έγινε ποτέ ευρωπαϊκή αποικία, με δικό της ημερολόγιο και δικό της αλφάβητο. Θεωρείται η πατρίδα του καφέ, και οι ορεινές εκκλησίες της στη Λαλιμπέλα είναι λαξευμένες μέσα στον συμπαγή βράχο.","fact":"Κατά τον θρύλο, ένας βοσκός ονόματι Κάλντι πρόσεξε πρώτος την τονωτική δράση των κόκκων του καφέ, εδώ στην Αιθιοπία.","wiki_en":"Ethiopia"},{"name":"Νιγηρία","emoji":"🇳🇬","meta":["Αφρική","Αμπούζα","περίπου 220 εκατ."],"description":"Η πολυπληθέστερη χώρα της Αφρικής, με εκατοντάδες εθνοτικές ομάδες και γλώσσες, και έδρα του Νόλιγουντ, μιας από τις μεγαλύτερες κινηματογραφικές βιομηχανίες του κόσμου σε παραγωγή. Η αφρομπίτς και άλλα νιγηριανά είδη ακούγονται πλέον παντού.","fact":"Πολλές ταινίες του Νόλιγουντ γυρίζονται σε λίγες εβδομάδες και βγαίνουν απευθείας σε βίντεο, χωρίς να περάσουν από τις αίθουσες.","wiki_en":"Nigeria"},{"name":"Μαδαγασκάρη","emoji":"🇲🇬","meta":["Αφρική","Ανταναναρίβο","περίπου 30 εκατ."],"description":"Ένα από τα μεγαλύτερα νησιά του πλανήτη, αποκομμένο από την ηπειρωτική χώρα για εκατομμύρια χρόνια, γι' αυτό και τα περισσότερα φυτά και ζώα του δεν ζουν αλλού. Οι λεμούριοι και τα παράξενα δέντρα μπαομπάμπ έγιναν τα φυσικά του σύμβολα.","fact":"Πάνω από το ενενήντα τοις εκατό των ειδών λεμούριων ζουν αποκλειστικά στη Μαδαγασκάρη και πουθενά αλλού στον κόσμο.","wiki_en":"Madagascar"},{"name":"Σεϋχέλλες","emoji":"🇸🇨","meta":["Αφρική","Βικτόρια","περίπου 100 χιλ."],"description":"Αρχιπέλαγος με πάνω από εκατό νησιά στον Ινδικό Ωκεανό, φημισμένο για τους γρανιτένιους βράχους στις κάτασπρες παραλίες και για τις γιγάντιες χελώνες που ζουν πάνω από έναν αιώνα. Είναι μία από τις λιγότερο πολυπληθείς χώρες του κόσμου.","fact":"Στην ατόλη Αλνταμπρά των Σεϋχελλών ζει ένας από τους μεγαλύτερους πληθυσμούς γιγάντιων χελωνών στον κόσμο.","wiki_en":"Seychelles"},{"name":"Μαυρίκιος","emoji":"🇲🇺","meta":["Αφρική","Πορ Λουί","περίπου 1,3 εκατ."],"description":"Νησιωτικό κράτος στον Ινδικό Ωκεανό, περιτριγυρισμένο από κοραλλιογενείς ύφαλους και γνωστό για το μείγμα ινδικών, αφρικανικών, ευρωπαϊκών και κινεζικών πολιτισμών. Εδώ ζούσε, πριν φτάσουν οι Ευρωπαίοι, το άπτερο πουλί ντόντο, σήμερα εντελώς εξαφανισμένο.","fact":"Ο Μαυρίκιος είναι ο μόνος γνωστός τόπος όπου ζούσε το ντόντο, που εξαφανίστηκε λίγες δεκαετίες μετά την ανακάλυψη του νησιού.","wiki_en":"Mauritius"},{"name":"Ινδία","emoji":"🇮🇳","meta":["Ασία","Νέο Δελχί","περίπου 1,44 δισ."],"description":"Η πολυπληθέστερη χώρα του κόσμου, όπου εκατοντάδες γλώσσες και θρησκείες πλέκονται σε έναν πολύχρωμο πολιτισμό. Το Τατζ Μαχάλ, τα μπαχαρικά και οι ταινίες του Μπόλιγουντ είναι γνωστά παντού, και η γιόγκα ξεκίνησε εδώ χιλιάδες χρόνια πριν.","fact":"Το Τατζ Μαχάλ χτίστηκε ως μαυσωλείο στη μνήμη της αγαπημένης συζύγου του αυτοκράτορα Σαχ Τζαχάν.","wiki_en":"India"},{"name":"Νεπάλ","emoji":"🇳🇵","meta":["Ασία","Κατμαντού","περίπου 30 εκατ."],"description":"Χώρα των Ιμαλαΐων, όπου βρίσκεται το Έβερεστ, η ψηλότερη κορυφή του πλανήτη και όνειρο ζωής για ορειβάτες από όλον τον κόσμο. Βουδιστικοί και ινδουιστικοί ναοί στο Κατμαντού βρίσκονται κοντά σε χωριά Σέρπα μέσα στις ορεινές κοιλάδες.","fact":"Το Νεπάλ είναι η μόνη χώρα στον κόσμο με σημαία που δεν είναι ορθογώνια, αλλά αποτελείται από δύο τρίγωνα.","wiki_en":"Nepal"},{"name":"Σρι Λάνκα","emoji":"🇱🇰","meta":["Ασία","Σρι Τζαγιαβαρδενεπούρα Κότε","περίπου 22 εκατ."],"description":"Νησιωτικό κράτος στο νότιο άκρο της Ινδίας, φημισμένο για τις φυτείες τσαγιού στα ορεινά του και για τις παραλίες του στον Ινδικό Ωκεανό. Αρχαίες οχυρωμένες πόλεις όπως η Σιγκιρίγια και βουδιστικοί ναοί κρατούν ζωντανή την ιστορία αιώνων.","fact":"Η Σρι Λάνκα είναι από τους μεγαλύτερους εξαγωγείς τσαγιού Κεϋλάνης, που πήρε το όνομά του από την παλιά ονομασία του νησιού.","wiki_en":"Sri Lanka"},{"name":"Μαλδίβες","emoji":"🇲🇻","meta":["Ασία","Μαλέ","περίπου 520 χιλ."],"description":"Αρχιπέλαγος με πάνω από χίλια κοραλλιογενή νησιά στον Ινδικό Ωκεανό, συνώνυμο των πολυτελών διακοπών σε μπάνγκαλοου πάνω από το νερό. Είναι η χώρα με το χαμηλότερο μέσο υψόμετρο στη Γη, κι αυτό την αφήνει εκτεθειμένη στην άνοδο της στάθμης.","fact":"Το Μαλέ, η πρωτεύουσα των Μαλδιβών, καλύπτει σχεδόν όλο το μικρό της νησί και είναι από τις πιο πυκνοδομημένες πόλεις του κόσμου.","wiki_en":"Maldives"},{"name":"Ταϊλάνδη","emoji":"🇹🇭","meta":["Ασία","Μπανγκόκ","περίπου 72 εκατ."],"description":"Η Νοτιοανατολική Ασία στην πιο πολύχρωμη εκδοχή της: χρυσοί βουδιστικοί ναοί, οι πολυσύχναστες αγορές της Μπανγκόκ και τροπικά νησιά όπως το Πουκέτ και το Πι Πι. Η ταϊλανδέζικη κουζίνα ισορροπεί το καυτερό, το ξινό, το γλυκό και το αλμυρό.","fact":"Η Ταϊλάνδη είναι η μόνη χώρα της Νοτιοανατολικής Ασίας που δεν έγινε ποτέ ευρωπαϊκή αποικία.","wiki_en":"Thailand"},{"name":"Βιετνάμ","emoji":"🇻🇳","meta":["Ασία","Ανόι","περίπου 100 εκατ."],"description":"Χώρα απλωμένη κατά μήκος της Νότιας Σινικής Θάλασσας, με αναβαθμίδες ρυζιού, τους ασβεστολιθικούς βράχους του κόλπου Χα Λονγκ και φαγητό του δρόμου όπως η σούπα φο. Ο βιετναμέζικος καφές με ζαχαρούχο γάλα έγινε κομμάτι της καθημερινότητας.","fact":"Ο κόλπος Χα Λονγκ, με τα χιλιάδες ασβεστολιθικά του νησιά, είναι στον κατάλογο παγκόσμιας κληρονομιάς της UNESCO.","wiki_en":"Vietnam"},{"name":"Καμπότζη","emoji":"🇰🇭","meta":["Ασία","Πνομ Πενχ","περίπου 17 εκατ."],"description":"Χώρα της Νοτιοανατολικής Ασίας, όπου μέσα από τη ζούγκλα υψώνεται το Ανγκόρ Βατ, το μεγαλύτερο ναϊκό συγκρότημα στον κόσμο. Το έκτισε η αυτοκρατορία των Χμερ περίπου χίλια χρόνια πριν, και ο ναός εικονίζεται ακόμη και στην εθνική σημαία.","fact":"Το Ανγκόρ Βατ χτίστηκε αρχικά ως ινδουιστικός ναός και αργότερα έγινε βουδιστικό ιερό.","wiki_en":"Cambodia"},{"name":"Μαλαισία","emoji":"🇲🇾","meta":["Ασία","Κουάλα Λουμπούρ","περίπου 34 εκατ."],"description":"Χώρα μοιρασμένη ανάμεσα στη Μαλαϊκή Χερσόνησο και το νησί Βόρνεο, όπου οι δίδυμοι πύργοι Πετρόνας στέκουν κοντά σε τροπικά δάση από τα αρχαιότερα του πλανήτη. Η μαλαισιανή κουζίνα ενώνει μαλαϊκές, κινεζικές και ινδικές παραδόσεις.","fact":"Οι πύργοι Πετρόνας στην Κουάλα Λουμπούρ παραμένουν τα ψηλότερα δίδυμα κτήρια στον κόσμο.","wiki_en":"Malaysia"},{"name":"Σιγκαπούρη","emoji":"🇸🇬","meta":["Ασία","Σιγκαπούρη","περίπου 6 εκατ."],"description":"Νησιωτική πόλη-κράτος στο άκρο της Μαλαϊκής Χερσονήσου, που μέσα σε μισό αιώνα πέρασε από ταπεινό λιμάνι σε παγκόσμιο χρηματοοικονομικό κέντρο. Οι Κήποι του Κόλπου, με τα γιγάντια τεχνητά «υπερδέντρα», έγιναν το σήμα της σύγχρονης πόλης.","fact":"Η Σιγκαπούρη είναι μία από τις λίγες πόλεις-κράτη του σύγχρονου κόσμου, μαζί με το Μονακό και το Βατικανό.","wiki_en":"Singapore"},{"name":"Ινδονησία","emoji":"🇮🇩","meta":["Ασία","Τζακάρτα","περίπου 280 εκατ."],"description":"Το μεγαλύτερο αρχιπέλαγος του πλανήτη, απλωμένο σε πάνω από δεκαεπτά χιλιάδες νησιά ανάμεσα στον Ινδικό και τον Ειρηνικό Ωκεανό. Το Μπαλί, με τις αναβαθμίδες ρυζιού και τους ινδουιστικούς ναούς του, είναι ο πιο γνωστός προορισμός της.","fact":"Η Ινδονησία είναι το μεγαλύτερο νησιωτικό κράτος της Γης και μία από τις πολυπληθέστερες χώρες του κόσμου.","wiki_en":"Indonesia"},{"name":"Φιλιππίνες","emoji":"🇵🇭","meta":["Ασία","Μανίλα","περίπου 115 εκατ."],"description":"Αρχιπέλαγος με πάνω από επτά χιλιάδες νησιά στη Νοτιοανατολική Ασία, που συγκεντρώνει δεκάδες γλώσσες και πολιτιστικές παραδόσεις. Οι κάτασπρες παραλίες του Μποράκαϊ και οι αναβαθμίδες ρυζιού του Μπανάουε, σκαλισμένες στα βουνά με τα χέρια, είναι το καμάρι της χώρας.","fact":"Οι κάτοικοι καλλιεργούν με τα χέρια τις αναβαθμίδες ρυζιού του Μπανάουε στο Λουζόν εδώ και αιώνες, κρατώντας ζωντανό ένα αρχαίο αρδευτικό σύστημα.","wiki_en":"Philippines"},{"name":"Νότια Κορέα","emoji":"🇰🇷","meta":["Ασία","Σεούλ","περίπου 52 εκατ."],"description":"Χώρα της Ανατολικής Ασίας που μέσα σε λίγες δεκαετίες πέρασε από τη φτώχεια στην τεχνολογική πρωτοπορία και χάρισε στον κόσμο την K-pop και τον κορεατικό κινηματογράφο. Το καυτερό κίμτσι και το φαγητό του δρόμου στη Σεούλ έγιναν κομμάτι της παγκόσμιας ποπ κουλτούρας.","fact":"Η Νότια Κορέα είναι από τις πρώτες χώρες στον κόσμο σε ταχύτητα διαδικτύου και σε επίπεδο τεχνολογικής ανάπτυξης.","wiki_en":"South Korea"},{"name":"Βόρεια Κορέα","emoji":"🇰🇵","meta":["Ασία","Πιονγκγιάνγκ","περίπου 26 εκατ."],"description":"Κράτος στο βόρειο τμήμα της Κορεατικής Χερσονήσου, με οροσειρές, πευκοδάση και το ηφαίστειο Πεκτού κοντά στα βόρεια σύνορα. Η πρωτεύουσα Πιονγκγιάνγκ ξεχωρίζει για τις φαρδιές λεωφόρους και τη μνημειακή αρχιτεκτονική των μέσων του 20ού αιώνα.","fact":"Το νενγκμιόν, κρύα νουντλς φαγόπυρου σε παγωμένο ζωμό, θεωρείται το χαρακτηριστικό πιάτο του Πιονγκγιάνγκ.","wiki_en":"North Korea"},{"name":"Μογγολία","emoji":"🇲🇳","meta":["Ασία","Ουλάν Μπατόρ","περίπου 3,5 εκατ."],"description":"Χώρα απέραντης στέπας ανάμεσα στη Ρωσία και την Κίνα, όπου η κτηνοτροφία και η ζωή στις γιούρτες από τσόχα παραμένουν καθημερινότητα για πολλές οικογένειες. Από εδώ ξεκίνησε τον 13ο αιώνα ο Τζένγκις Χαν τη μεγαλύτερη χερσαία αυτοκρατορία της ιστορίας.","fact":"Η Μογγολία είναι από τις λιγότερο πυκνοκατοικημένες χώρες του κόσμου: σε ένα τεράστιο έδαφος ζουν μόλις λίγα εκατομμύρια άνθρωποι.","wiki_en":"Mongolia"},{"name":"Αυστραλία","emoji":"🇦🇺","meta":["Ωκεανία","Καμπέρα","περίπου 26 εκατ."],"description":"Χώρα που είναι ταυτόχρονα και ήπειρος, με πανίδα που δεν συναντάς αλλού και με τον Μεγάλο Κοραλλιογενή Φραγμό, το μεγαλύτερο κοραλλιογενές σύστημα του πλανήτη. Η Όπερα του Σίδνεϊ, με τη στέγη σαν πανιά, είναι από τα πιο αναγνωρίσιμα κτήρια στον κόσμο.","fact":"Τα περισσότερα ζώα της Αυστραλίας, μαζί με τα καγκουρό και τα κοάλα, δεν ζουν ελεύθερα πουθενά αλλού στον κόσμο.","wiki_en":"Australia"},{"name":"Νέα Ζηλανδία","emoji":"🇳🇿","meta":["Ωκεανία","Ουέλινγκτον","περίπου 5,2 εκατ."],"description":"Νησιωτικό κράτος με καταπράσινους λόφους, φιόρδ και ηφαίστεια, που έγινε το φυσικό σκηνικό της τριλογίας «Ο Άρχοντας των Δαχτυλιδιών». Η κουλτούρα των Μαορί, με τον πολεμικό χορό χάκα, παραμένει ζωντανό κομμάτι της εθνικής ταυτότητας.","fact":"Για μεγάλο διάστημα της ιστορίας της, η Νέα Ζηλανδία είχε πολλές φορές περισσότερα πρόβατα από ανθρώπους.","wiki_en":"New Zealand"},{"name":"Φίτζι","emoji":"🇫🇯","meta":["Ωκεανία","Σούβα","περίπου 930 χιλ."],"description":"Αρχιπέλαγος με πάνω από τριακόσια τροπικά νησιά στον νότιο Ειρηνικό, φημισμένο για τους κοραλλιογενείς ύφαλους και τη ζεστασιά των κατοίκων. Για μια τόσο μικρή χώρα, το Φίτζι έχει από τις δυνατότερες ομάδες ράγκμπι επτάδων στον κόσμο.","fact":"Το χρυσό μετάλλιο του Φίτζι στο ράγκμπι επτάδων στους Ολυμπιακούς του 2016 ήταν το πρώτο ολυμπιακό μετάλλιο της χώρας.","wiki_en":"Fiji"},{"name":"Καναδάς","emoji":"🇨🇦","meta":["Βόρεια Αμερική","Οτάβα","περίπου 40 εκατ."],"description":"Η δεύτερη μεγαλύτερη χώρα του κόσμου, που απλώνεται από τον Ατλαντικό μέχρι τον Ειρηνικό, με απέραντα δάση, λίμνες και τα Βραχώδη Όρη. Το φύλλο σφενδάμου στη σημαία και το χόκεϊ επί πάγου είναι από παλιά εθνικά σύμβολα.","fact":"Ο Καναδάς έχει τη μεγαλύτερη σε μήκος ακτογραμμή από κάθε άλλη χώρα στον κόσμο.","wiki_en":"Canada"},{"name":"Μεξικό","emoji":"🇲🇽","meta":["Βόρεια Αμερική","Πόλη του Μεξικού","περίπου 129 εκατ."],"description":"Η γη των αρχαίων Μάγια και Αζτέκων, με πυραμίδες που υψώνονται ακόμη μέσα από τη ζούγκλα και την έρημο. Η μεξικανική κουζίνα, με την τεκίλα, τα τάκος και τις καυτερές σάλτσες, αναγνωρίζεται από την UNESCO ως άυλη πολιτιστική κληρονομιά.","fact":"Η Ημέρα των Νεκρών στο Μεξικό δεν έχει να κάνει με το πένθος, αλλά με τη χαρούμενη ανάμνηση των συγγενών που έφυγαν.","wiki_en":"Mexico"},{"name":"Κούβα","emoji":"🇨🇺","meta":["Βόρεια Αμερική","Αβάνα","περίπου 11 εκατ."],"description":"Το μεγαλύτερο νησί της Καραϊβικής, φημισμένο για τα αυτοκίνητα της δεκαετίας του 1950 που κυκλοφορούν ακόμη στους δρόμους της Αβάνας και για τους ρυθμούς της σάλσα και της ρούμπα. Το κουβανικό ρούμι και τα πούρα θεωρούνται από τα καλύτερα στον κόσμο.","fact":"Τα κουβανικά πούρα τυλίγονται στο χέρι, και ο καλύτερος καπνός για αυτά καλλιεργείται στη δυτική κοιλάδα Βουέλτα Αμπάχο.","wiki_en":"Cuba"},{"name":"Τζαμάικα","emoji":"🇯🇲","meta":["Βόρεια Αμερική","Κίνγκστον","περίπου 2,8 εκατ."],"description":"Νησί της Καραϊβικής που χάρισε στον κόσμο τη ρέγκε και τον Μπομπ Μάρλεϊ, αλλά και σπρίντερ που κυριαρχούν στις ολυμπιακές πίστες εδώ και δεκαετίες. Οι παραλίες με τη λευκή άμμο και τα Μπλου Μάουντινς με τις φυτείες καφέ τραβούν επισκέπτες από παντού.","fact":"Οι Τζαμαϊκανοί σπρίντερ, με τον Γιουσέιν Μπολτ στην κορυφή, έσπασαν παγκόσμια ρεκόρ στον στίβο για πολλά χρόνια.","wiki_en":"Jamaica"},{"name":"Δομινικανή Δημοκρατία","emoji":"🇩🇴","meta":["Βόρεια Αμερική","Σάντο Ντομίνγκο","περίπου 11 εκατ."],"description":"Χώρα της Καραϊβικής που μοιράζεται το νησί Ισπανιόλα με την Αϊτή, με τις κάτασπρες παραλίες της Πούντα Κάνα και τους ρυθμούς της μερένγκε και της μπατσάτα. Το Σάντο Ντομίνγκο θεωρείται η παλαιότερη συνεχώς κατοικημένη πόλη της Αμερικής.","fact":"Η μπατσάτα, που γεννήθηκε στη δομινικανή επαρχία, εξελίχθηκε με τον καιρό σε χορευτικό είδος δημοφιλές σε όλον τον κόσμο.","wiki_en":"Dominican Republic"},{"name":"Μπαχάμες","emoji":"🇧🇸","meta":["Βόρεια Αμερική","Νασάου","περίπου 400 χιλ."],"description":"Αρχιπέλαγος με εφτακόσια περίπου νησιά και νησίδες στον Ατλαντικό, κοντά στη Φλόριδα, φημισμένο για τα γαλαζοπράσινα νερά και τους κοραλλιογενείς ύφαλους. Εδώ, σύμφωνα με την επικρατούσα εκδοχή, αποβιβάστηκε πρώτη φορά ο Χριστόφορος Κολόμβος το 1492.","fact":"Οι Μπαχάμες είναι γνωστές για τις «γαλάζιες τρύπες», βαθιές υποβρύχιες καταβόθρες στον ασβεστόλιθο που τραβούν δύτες από παντού.","wiki_en":"The Bahamas"},{"name":"Κόστα Ρίκα","emoji":"🇨🇷","meta":["Βόρεια Αμερική","Σαν Χοσέ","περίπου 5,2 εκατ."],"description":"Χώρα της Κεντρικής Αμερικής που κατάργησε τον μόνιμο στρατό της και έβαλε τα χρήματα στην προστασία των τροπικών δασών, όπου ζει τεράστια ποικιλία ζώων και φυτών. Ηφαίστεια, δάση μέσα στα σύννεφα και παραλίες σε δύο ωκεανούς την κάνουν μαγνήτη οικοτουρισμού.","fact":"Σχεδόν όλο το ρεύμα της Κόστα Ρίκα παράγεται από ανανεώσιμες πηγές: υδροηλεκτρικά, ηφαιστειακή θερμότητα και άνεμο.","wiki_en":"Costa Rica"},{"name":"Παναμάς","emoji":"🇵🇦","meta":["Βόρεια Αμερική","Πόλη του Παναμά","περίπου 4,4 εκατ."],"description":"Στενός ισθμός ανάμεσα στις δύο Αμερικές, που τον διασχίζει η Διώρυγα του Παναμά, ένα από τα σημαντικότερα τεχνητά υδάτινα περάσματα του παγκόσμιου εμπορίου. Οι πύργοι της πρωτεύουσας γειτονεύουν με πυκνά τροπικά δάση και με τις κοινότητες των ιθαγενών Γκούνα.","fact":"Η Διώρυγα του Παναμά συνδέει τον Ατλαντικό με τον Ειρηνικό Ωκεανό και περνούν από αυτήν δεκάδες πλοία κάθε μέρα.","wiki_en":"Panama"},{"name":"Βραζιλία","emoji":"🇧🇷","meta":["Νότια Αμερική","Μπραζίλια","περίπου 216 εκατ."],"description":"Η μεγαλύτερη χώρα της Νότιας Αμερικής, στο έδαφος της οποίας βρίσκεται το μεγαλύτερο μέρος του Αμαζονίου, του μεγαλύτερου τροπικού δάσους του πλανήτη. Το καρναβάλι του Ρίο, το ποδόσφαιρο και ο Χριστός του Κορκοβάντο είναι σύμβολα που τα αναγνωρίζουν όλοι.","fact":"Η Βραζιλία είναι η μόνη πορτογαλόφωνη χώρα της Νότιας Αμερικής, κατάλοιπο του αποικιακού παρελθόντος της.","wiki_en":"Brazil"},{"name":"Αργεντινή","emoji":"🇦🇷","meta":["Νότια Αμερική","Μπουένος Άιρες","περίπου 46 εκατ."],"description":"Η χώρα του τανγκό, των απέραντων λιβαδιών της πάμπας με τους γκάουτσο κτηνοτρόφους και των χιονισμένων κορυφών της Παταγονίας στον βαθύ νότο. Το αργεντίνικο βοδινό και το ποδόσφαιρο που έβγαλε τον Μαραντόνα και τον Μέσι είναι εθνικό καμάρι.","fact":"Ο παγετώνας Περίτο Μορένο στην Παταγονία ρίχνει με βοή τεράστιους όγκους πάγου στη λίμνη, μπροστά στα μάτια των επισκεπτών.","wiki_en":"Argentina"},{"name":"Χιλή","emoji":"🇨🇱","meta":["Νότια Αμερική","Σαντιάγο","περίπου 19,6 εκατ."],"description":"Μια στενή λωρίδα χώρας κατά μήκος των ακτών του Ειρηνικού, που περιλαμβάνει την έρημο Ατακάμα, ένα από τα πιο άνυδρα μέρη της Γης, και τις χιονισμένες κορυφές των Άνδεων. Τα αμπέλια της Χιλής δίνουν από τα καλύτερα κρασιά του νότιου ημισφαιρίου.","fact":"Η Χιλή απλώνεται σχεδόν τέσσερις χιλιάδες πεντακόσια χιλιόμετρα από βορρά προς νότο, μένοντας εντυπωσιακά στενή.","wiki_en":"Chile"},{"name":"Περού","emoji":"🇵🇪","meta":["Νότια Αμερική","Λίμα","περίπου 34 εκατ."],"description":"Χώρα των Άνδεων που φυλάει τα ερείπια του Μάτσου Πίτσου, της χαμένης πόλης των Ίνκας ψηλά στα βουνά και ενός από τα νέα θαύματα του κόσμου. Η περουβιανή κουζίνα, με ντόπιες και μεταναστευτικές παραδόσεις μαζί, θεωρείται από τις πιο πλούσιες στον κόσμο.","fact":"Το Μάτσου Πίτσου χτίστηκε από τους Ίνκας τον 15ο αιώνα και έμεινε άγνωστο στον έξω κόσμο μέχρι τις αρχές του 20ού.","wiki_en":"Peru"},{"name":"Βενεζουέλα","emoji":"🇻🇪","meta":["Νότια Αμερική","Καράκας","περίπου 28 εκατ."],"description":"Χώρα στον βορρά της Νότιας Αμερικής, όπου βρίσκεται ο Ανχέλ, ο ψηλότερος καταρράκτης του κόσμου, που πέφτει από ένα επίπεδο οροπέδιο κατευθείαν μέσα στη ζούγκλα. Η ακτή της Καραϊβικής και οι χιονισμένες Άνδεις γειτονεύουν με τις απέραντες πεδιάδες των γιάνος.","fact":"Ο καταρράκτης Ανχέλ είναι σχεδόν είκοσι φορές ψηλότερος από τον Νιαγάρα και θεωρείται ο ψηλότερος του πλανήτη.","wiki_en":"Venezuela"},{"name":"Βολιβία","emoji":"🇧🇴","meta":["Νότια Αμερική","Σούκρε και Λα Πας","περίπου 12 εκατ."],"description":"Χώρα στην καρδιά των Άνδεων, όπου βρίσκεται το Σαλάρ ντε Ουγιούνι, η μεγαλύτερη αλυκή του κόσμου, που μετά τις βροχές γίνεται ένας τεράστιος καθρέφτης. Η Λα Πας, έδρα της κυβέρνησης, είναι από τις ψηλότερες πρωτεύουσες της Γης.","fact":"Η Λα Πας βρίσκεται τόσο ψηλά και σε τόσο απότομες πλαγιές που ένα δίκτυο τελεφερίκ έχει αναλάβει μέρος των συγκοινωνιών της.","wiki_en":"Bolivia"},{"name":"Ουρουγουάη","emoji":"🇺🇾","meta":["Νότια Αμερική","Μοντεβιδέο","περίπου 3,4 εκατ."],"description":"Μικρή χώρα στις ακτές του Ατλαντικού, ανάμεσα στην Αργεντινή και τη Βραζιλία, όπου το ποδόσφαιρο μοιάζει με θρησκεία και όπου έγινε το πρώτο Παγκόσμιο Κύπελλο της ιστορίας, το 1930. Οι Ουρουγουανοί είναι από τους πιο φανατικούς πότες του μάτε στον κόσμο.","fact":"Η Ουρουγουάη διοργάνωσε και κέρδισε το πρώτο Παγκόσμιο Κύπελλο ποδοσφαίρου, το 1930.","wiki_en":"Uruguay"},{"name":"Κολομβία","emoji":"🇨🇴","meta":["Νότια Αμερική","Μπογκοτά","περίπου 52 εκατ."],"description":"Η πατρίδα του φημισμένου ορεινού καφέ αραβίκα και των σημαντικότερων κοιτασμάτων σμαραγδιού στον κόσμο, που εξορύσσονται εδώ αιώνες. Ακτές στον Ειρηνικό και την Καραϊβική, χιονισμένες Άνδεις και τεράστιες ανθοκομικές φυτείες δίνουν εντυπωσιακή ποικιλία τοπίων.","fact":"Η Κολομβία είναι η μόνη χώρα της Νότιας Αμερικής με ακτές ταυτόχρονα στον Ειρηνικό και στον Ατλαντικό Ωκεανό.","wiki_en":"Colombia"},{"name":"Ισημερινός","emoji":"🇪🇨","meta":["Νότια Αμερική","Κίτο","περίπου 18 εκατ."],"description":"Η χώρα πήρε το όνομά της από τον ισημερινό, που περνά από το βόρειο τμήμα της. Σε μικρή έκταση συνυπάρχουν τα χιονισμένα ηφαίστεια των Άνδεων, η ζούγκλα του Αμαζονίου και τα νησιά Γκαλαπάγκος με τη μοναδική τους πανίδα.","fact":"Τα νησιά Γκαλαπάγκος, που ανήκουν στον Ισημερινό, ενέπνευσαν στον Κάρολο Δαρβίνο τη θεωρία της εξέλιξης.","wiki_en":"Ecuador"},{"name":"Παραγουάη","emoji":"🇵🇾","meta":["Νότια Αμερική","Ασουνσιόν","περίπου 6,8 εκατ."],"description":"Μία από τις δύο χώρες της Νότιας Αμερικής χωρίς έξοδο στη θάλασσα, πλούσια όμως σε γλυκό νερό και υδροηλεκτρική ενέργεια. Η γλώσσα γουαρανί μιλιέται εδώ ακόμη ευρύτατα, στο ίδιο επίπεδο με τα ισπανικά.","fact":"Τα γουαρανί είναι από τις λίγες ιθαγενείς γλώσσες της Αμερικής με επίσημο καθεστώς ισότιμο με τα ισπανικά.","wiki_en":"Paraguay"},{"name":"Γουατεμάλα","emoji":"🇬🇹","meta":["Βόρεια Αμερική","Πόλη της Γουατεμάλας","περίπου 18 εκατ."],"description":"Η γη των Μάγια, με μερικά από τα πιο εντυπωσιακά ερείπια αυτού του πολιτισμού μέσα σε πυκνά τροπικά δάση. Ηφαίστεια, φυτείες καφέ και τα ζωηρά υφαντά μοτίβα των ιθαγενών κοινοτήτων δίνουν τον χαρακτήρα της σημερινής Γουατεμάλας.","fact":"Η αρχαία πόλη των Μάγια Τικάλ, κρυμμένη στη ζούγκλα της Γουατεμάλας, έμεινε για αιώνες θαμμένη κάτω από τη βλάστηση.","wiki_en":"Guatemala"},{"name":"Ονδούρα","emoji":"🇭🇳","meta":["Βόρεια Αμερική","Τεγκουσιγκάλπα","περίπου 10 εκατ."],"description":"Χώρα με εκτεταμένους κοραλλιογενείς ύφαλους στην ακτή της Καραϊβικής και πυκνά τροπικά δάση στο εσωτερικό. Στο έδαφός της βρίσκεται η Κοπάν, μία από τις σημαντικότερες πόλεις του αρχαίου πολιτισμού των Μάγια.","fact":"Ο φραγμός κοραλλιών στις ακτές της Ονδούρας ανήκει στο δεύτερο μεγαλύτερο κοραλλιογενές σύστημα του κόσμου, μετά τον Μεγάλο Κοραλλιογενή Φραγμό.","wiki_en":"Honduras"},{"name":"Ελ Σαλβαδόρ","emoji":"🇸🇻","meta":["Βόρεια Αμερική","Σαν Σαλβαδόρ","περίπου 6,3 εκατ."],"description":"Η μικρότερη σε έκταση χώρα της ηπειρωτικής Αμερικής, με δεκάδες ηφαίστεια όμως και μια ακτή του Ειρηνικού που οι σέρφερ γνωρίζουν καλά. Οι πουπούσας, χοντρές γεμιστές πίτες από καλαμποκάλευρο, είναι το βασικό πιάτο της τοπικής κουζίνας.","fact":"Το Ελ Σαλβαδόρ είναι η μόνη χώρα της Κεντρικής Αμερικής που δεν έχει ακτές στην Καραϊβική Θάλασσα.","wiki_en":"El Salvador"},{"name":"Νικαράγουα","emoji":"🇳🇮","meta":["Βόρεια Αμερική","Μανάγουα","περίπου 6,8 εκατ."],"description":"Χώρα λιμνών και ηφαιστείων: στη λίμνη Νικαράγουα, τη μεγαλύτερη της Κεντρικής Αμερικής, ζουν καρχαρίες ταύροι του γλυκού νερού, σπάνιο φαινόμενο για εσωτερικά νερά. Η αποικιακή αρχιτεκτονική της Γρανάδα και της Λεόν γειτονεύει με ενεργά ηφαίστεια.","fact":"Μέσα στη λίμνη Νικαράγουα βρίσκεται το νησί Ομετέπε, που σχηματίστηκε από δύο ηφαίστεια ενωμένα με έναν στενό ισθμό.","wiki_en":"Nicaragua"},{"name":"Αϊτή","emoji":"🇭🇹","meta":["Βόρεια Αμερική","Πορτ-ο-Πρενς","περίπου 11 εκατ."],"description":"Η πρώτη ανεξάρτητη μαύρη δημοκρατία στον κόσμο, που γεννήθηκε από εξέγερση σκλάβων στις αρχές του 19ου αιώνα. Μοιράζεται το νησί Ισπανιόλα με τη Δομινικανή Δημοκρατία και είναι γνωστή για τη ζωηρή ναΐφ ζωγραφική και τους ρυθμούς κομπά.","fact":"Το όνομα «Αϊτή» έρχεται από τη γλώσσα των Ταΐνο, των ιθαγενών του νησιού, και μεταφράζεται ως «ορεινή γη».","wiki_en":"Haiti"},{"name":"Τρινιντάντ και Τομπάγκο","emoji":"🇹🇹","meta":["Βόρεια Αμερική","Πορτ οφ Σπέιν","περίπου 1,4 εκατ."],"description":"Η πατρίδα των μεταλλικών τυμπάνων παν και της καρναβαλικής μουσικής κάλυψο, από την οποία ξεπήδησε ένα σωρό είδη της Καραϊβικής. Το Τομπάγκο φημίζεται για τους κοραλλιογενείς ύφαλους, το Τρινιντάντ για το πετρέλαιο και το ξέφρενο καρναβάλι του.","fact":"Στο Τρινιντάντ βρίσκεται η Πιτς Λέικ, το μεγαλύτερο φυσικό κοίτασμα ασφάλτου στον κόσμο.","wiki_en":"Trinidad and Tobago"},{"name":"Μπαρμπάντος","emoji":"🇧🇧","meta":["Βόρεια Αμερική","Μπρίτζταουν","περίπου 280 χιλ."],"description":"Μικρό κοραλλιογενές νησί, το ανατολικότερο της αλυσίδας των Μικρών Αντιλλών, που βρίσκεται πλέον μέσα στα νερά του Ατλαντικού. Εδώ γεννήθηκε το ρούμι στη σημερινή του μορφή, και οι ανοιχτόχρωμες αμμουδιές του τραβούν επισκέπτες από παντού.","fact":"Το Μπαρμπάντος θεωρείται ο τόπος όπου παρήχθη για πρώτη φορά ρούμι σε βιομηχανική κλίμακα.","wiki_en":"Barbados"},{"name":"Σλοβακία","emoji":"🇸🇰","meta":["Ευρώπη","Μπρατισλάβα","περίπου 5,5 εκατ."],"description":"Ορεινή χώρα στην καρδιά της Ευρώπης, όπου τα Τάτρα παντρεύουν αλπικά τοπία με ξύλινες κωμοπόλεις και κάστρα πάνω σε βράχια. Στην Μπρατισλάβα, την πρωτεύουσα πάνω στον Δούναβη, νιώθεις ακόμη τη μίξη αυστριακών, ουγγρικών και σλαβικών επιρροών.","fact":"Στη Σλοβακία σώζονται πάνω από εκατό κάστρα και φρούρια, εντυπωσιακός αριθμός για μια τόσο μικρή χώρα.","wiki_en":"Slovakia"},{"name":"Λουξεμβούργο","emoji":"🇱🇺","meta":["Ευρώπη","Λουξεμβούργο","περίπου 660 χιλ."],"description":"Μία από τις μικρότερες χώρες της Ευρώπης και ταυτόχρονα παγκόσμιο χρηματοοικονομικό κέντρο, με ένα από τα υψηλότερα κατά κεφαλήν εισοδήματα. Στη μικροσκοπική πρωτεύουσα, μεσαιωνικά τείχη γειτονεύουν με γυάλινους πύργους τραπεζών.","fact":"Δεκάδες χιλιάδες άνθρωποι έρχονται καθημερινά στο Λουξεμβούργο για δουλειά από τη Γαλλία, τη Γερμανία και το Βέλγιο.","wiki_en":"Luxembourg"},{"name":"Λιχτενστάιν","emoji":"🇱🇮","meta":["Ευρώπη","Βαντούζ","περίπου 40 χιλ."],"description":"Μικροσκοπικό αλπικό πριγκιπάτο ανάμεσα στην Ελβετία και την Αυστρία, όπου κυβερνά ακόμη κληρονομική μοναρχία. Οι πίστες του σκι, το μεσαιωνικό κάστρο πάνω από την πρωτεύουσα και το πολύ υψηλό κατά κεφαλήν ΑΕΠ το κρατούν στον χάρτη παρά το μέγεθός του.","fact":"Το Λιχτενστάιν είναι από τις λίγες χώρες του κόσμου χωρίς κανένα αεροδρόμιο με τακτικές πτήσεις.","wiki_en":"Liechtenstein"},{"name":"Ανδόρα","emoji":"🇦🇩","meta":["Ευρώπη","Ανδόρα λα Βέγια","περίπου 80 χιλ."],"description":"Κράτος σφηνωμένο στα Πυρηναία, ανάμεσα στην Ισπανία και τη Γαλλία, που για αιώνες κυβερνήθηκε από δύο συνηγεμόνες, έναν Γάλλο και έναν Ισπανό. Σήμερα είναι γνωστό για τα χιονοδρομικά του και για τις αφορολόγητες αγορές που τραβούν κόσμο από όλη την Ευρώπη.","fact":"Αρχηγοί του κράτους της Ανδόρας θεωρούνται επίσημα, μαζί, ο πρόεδρος της Γαλλίας και ο ισπανός επίσκοπος της Ουρζέλ.","wiki_en":"Andorra"},{"name":"Άγιος Μαρίνος","emoji":"🇸🇲","meta":["Ευρώπη","Άγιος Μαρίνος","περίπου 34 χιλ."],"description":"Μία από τις παλαιότερες δημοκρατίες του κόσμου, στις πλαγιές του όρους Τιτάνο, μέσα στους λόφους της Ιταλίας, που περικυκλώνει εντελώς το μικροσκοπικό κράτος. Οι τρεις μεσαιωνικοί πύργοι πάνω από την πρωτεύουσα είναι το έμβλημά του και μνημείο της UNESCO.","fact":"Κατά την παράδοση ο Άγιος Μαρίνος ιδρύθηκε τον 4ο αιώνα και θεωρείται ένα από τα παλαιότερα κράτη που υπάρχουν ακόμη.","wiki_en":"San Marino"},{"name":"Αλβανία","emoji":"🇦🇱","meta":["Ευρώπη","Τίρανα","περίπου 2,8 εκατ."],"description":"Ορεινή βαλκανική χώρα με μεγάλη ακτογραμμή στην Αδριατική και το Ιόνιο, που τα τελευταία χρόνια συγκρίνεται με ακριβότερα θέρετρα της Μεσογείου. Δεκαετίες απομόνωσης άφησαν εμφανές σημάδι στο τοπίο: χιλιάδες μικρά τσιμεντένια οχυρά σκορπισμένα παντού.","fact":"Σε όλη την Αλβανία στέκουν ακόμη χιλιάδες τσιμεντένια οχυρά, χτισμένα στο δεύτερο μισό του 20ού αιώνα.","wiki_en":"Albania"},{"name":"Βόρεια Μακεδονία","emoji":"🇲🇰","meta":["Ευρώπη","Σκόπια","περίπου 1,8 εκατ."],"description":"Μικρή βαλκανική χώρα γύρω από τα Σκόπια, από την οποία περνούσαν κάποτε σημαντικοί εμπορικοί δρόμοι μεταξύ Ευρώπης και Ασίας. Η αρχαιότητα συνυπάρχει εδώ με οθωμανική αρχιτεκτονική και γραφικές ορεινές λίμνες, ανάμεσά τους η Λίμνη Αχρίδα.","fact":"Η Λίμνη Αχρίδα, στα σύνορα Βόρειας Μακεδονίας και Αλβανίας, είναι μία από τις παλαιότερες λίμνες της Ευρώπης, ηλικίας εκατομμυρίων ετών.","wiki_en":"North Macedonia"},{"name":"Βοσνία και Ερζεγοβίνη","emoji":"🇧🇦","meta":["Ευρώπη","Σαράγεβο","περίπου 3,3 εκατ."],"description":"Βαλκανική χώρα όπου συναντιούνται η οθωμανική, η αυστροουγγρική και η σλαβική κληρονομιά, πιο καθαρά στο Σαράγεβο και στο Μόσταρ. Ορμητικά ποτάμια, φαράγγια και παλιά πέτρινα γεφύρια δίνουν στο τοπίο της δική του φυσιογνωμία.","fact":"Το γεφύρι Στάρι Μοστ στο Μόσταρ, υπό την προστασία της UNESCO, είναι δείγμα οθωμανικής μηχανικής του 16ου αιώνα.","wiki_en":"Bosnia and Herzegovina"},{"name":"Μολδαβία","emoji":"🇲🇩","meta":["Ευρώπη","Κισινάου","περίπου 2,5 εκατ."],"description":"Μικρή χώρα ανάμεσα στη Ρουμανία και την Ουκρανία, γνωστή για τα εύφορα εδάφη της και τη μακρά οινική της παράδοση. Τα μολδαβικά κελάρια της Κρικόβα και του Μιλέστι Μίτσι είναι από τις μεγαλύτερες αποθήκες κρασιού του πλανήτη.","fact":"Στα υπόγεια τούνελ του οινοποιείου Μιλέστι Μίτσι φυλάσσεται μία από τις μεγαλύτερες συλλογές κρασιού στον κόσμο.","wiki_en":"Moldova"},{"name":"Πακιστάν","emoji":"🇵🇰","meta":["Ασία","Ισλαμαμπάντ","περίπου 240 εκατ."],"description":"Χώρα στους πρόποδες του Καρακόραμ και των Ιμαλαΐων, με μερικές από τις ψηλότερες κορυφές του πλανήτη, ανάμεσά τους το K2. Η κοιλάδα του Ινδού ήταν κοιτίδα ενός από τους αρχαιότερους πολιτισμούς, και σήμερα το Πακιστάν φημίζεται για τα καυτερά φαγητά και τη φιλοξενία.","fact":"Το όρος K2, στο έδαφος του Πακιστάν, είναι η δεύτερη ψηλότερη κορυφή της Γης μετά το Έβερεστ.","wiki_en":"Pakistan"},{"name":"Μπανγκλαντές","emoji":"🇧🇩","meta":["Ασία","Ντάκα","περίπου 170 εκατ."],"description":"Χώρα χτισμένη στο δέλτα του Γάγγη και του Βραχμαπούτρα, πλεγμένη με κανάλια και ορυζώνες, και μία από τις πιο πυκνοκατοικημένες του κόσμου. Στον νότο βρίσκονται τα Σουντάρμπανς, το μεγαλύτερο δάσος μαγγροβίων στον πλανήτη, όπου ζουν τίγρεις της Βεγγάλης.","fact":"Το Μπανγκλαντές περικυκλώνεται σχεδόν ολόκληρο από την Ινδία και έχει μόνο ένα σύντομο σύνορο με τη Μιανμάρ στα νοτιοανατολικά.","wiki_en":"Bangladesh"},{"name":"Αφγανιστάν","emoji":"🇦🇫","meta":["Ασία","Καμπούλ","περίπου 40 εκατ."],"description":"Ορεινή χώρα στο σταυροδρόμι των αρχαίων εμπορικών δρόμων του Δρόμου του Μεταξιού, όπου για αιώνες ανακατεύτηκαν ο περσικός, ο ινδικός και ο κεντροασιατικός πολιτισμός. Ο μιναρές του Τζαμ και το Γαλάζιο Τζαμί στο Μαζάρι Σαρίφ είναι από τα σημαντικότερα μνημεία της περιοχής.","fact":"Στο αφγανικό Μπαντακσάν εξορύσσεται λαζουρίτης εδώ και χιλιάδες χρόνια: η γαλάζια πέτρα έφτανε ως την Αίγυπτο και τη Μεσοποταμία.","wiki_en":"Afghanistan"},{"name":"Ιράκ","emoji":"🇮🇶","meta":["Ασία","Βαγδάτη","περίπου 44 εκατ."],"description":"Η γη ανάμεσα στον Τίγρη και τον Ευφράτη, γνωστή ως Μεσοποταμία, όπου εμφανίστηκαν μερικές από τις πρώτες πόλεις και η πρώτη γραφή. Η κληρονομιά των Σουμερίων, της Βαβυλώνας και του Ακκάδ κάνει την περιοχή κλειδί για την ιστορία του πολιτισμού.","fact":"Η σφηνοειδής γραφή, ένα από τα αρχαιότερα συστήματα γραφής στον κόσμο, γεννήθηκε στη Μεσοποταμία, στο σημερινό Ιράκ.","wiki_en":"Iraq"},{"name":"Συρία","emoji":"🇸🇾","meta":["Ασία","Δαμασκός","περίπου 22 εκατ."],"description":"Χώρα με μία από τις αρχαιότερες συνεχώς κατοικημένες πρωτεύουσες του κόσμου: η Δαμασκός αναφέρεται σε γραπτές πηγές εδώ και χιλιετίες. Από το έδαφός της περνούσαν από παλιά οι εμπορικοί δρόμοι που ένωναν τη Μεσόγειο με τη Μεσοποταμία και την Αραβία.","fact":"Από το όνομα της συριακής πρωτεύουσας βγήκαν η λέξη «δαμασκηνό» για το κεντητό ύφασμα και ο «δαμασκηνός χάλυβας».","wiki_en":"Syria"},{"name":"Λίβανος","emoji":"🇱🇧","meta":["Ασία","Βηρυτός","περίπου 5,5 εκατ."],"description":"Μικρή χώρα στην ανατολική ακτή της Μεσογείου, της οποίας τα ορεινά κέδρα χρησιμοποιούσαν οι Φοίνικες για να φτιάχνουν πλοία και αναφέρονται σε αρχαία κείμενα. Η Βηρυτός ήταν για αιώνες σταυροδρόμι εμπορίου και πολιτισμών της περιοχής.","fact":"Ο κέδρος του Λιβάνου, που φυτρώνει στα βουνά της χώρας, εικονίζεται στην εθνική σημαία.","wiki_en":"Lebanon"},{"name":"Υεμένη","emoji":"🇾🇪","meta":["Ασία","Σαναά","περίπου 33 εκατ."],"description":"Χώρα στον νότο της Αραβικής Χερσονήσου με πολυώροφα σπίτια από πηλό: η παλιά πόλη Σιμπάμ ονομάστηκε γι' αυτά «Μανχάταν της ερήμου». Το νησί Σοκότρα, στα ανοιχτά της, φημίζεται για φυτά που δεν υπάρχουν πουθενά αλλού στη Γη.","fact":"Στο νησί Σοκότρα, που ανήκει στην Υεμένη, φυτρώνει το δέντρο του δράκου, με τη χαρακτηριστική κόμη-ομπρέλα, μοναδικό στον κόσμο.","wiki_en":"Yemen"},{"name":"Κουβέιτ","emoji":"🇰🇼","meta":["Ασία","Πόλη του Κουβέιτ","περίπου 4,3 εκατ."],"description":"Μικρό κράτος στο βόρειο άκρο του Περσικού Κόλπου, από τα πλουσιότερα του κόσμου χάρη στο πετρέλαιο που βρέθηκε στα μέσα του 20ού αιώνα. Πριν την εποχή του πετρελαίου, το Κουβέιτ ήταν γνωστό ως κέντρο αλιείας μαργαριταριών και ναυτικού εμπορίου.","fact":"Το όνομα της χώρας προέρχεται από την αραβική λέξη «κουτ», που σήμαινε μικρό οχυρό δίπλα στο νερό.","wiki_en":"Kuwait"},{"name":"Μπαχρέιν","emoji":"🇧🇭","meta":["Ασία","Μαναμά","περίπου 1,5 εκατ."],"description":"Νησιωτικό κράτος στον Περσικό Κόλπο, από τα πρώτα στην περιοχή που άρχισαν την εξόρυξη πετρελαίου, ήδη στη δεκαετία του 1930. Το Μπαχρέιν είναι γνωστό και για τους αρχαίους τάφους του Ντιλμούν και για την πίστα της Formula 1, που φιλοξενεί αγώνες από τα μέσα της δεκαετίας του 2000.","fact":"Το Μπαχρέιν συνδέεται με τη Σαουδική Αραβία μέσω της γέφυρας του Βασιλιά Φαχντ, μήκους περίπου είκοσι πέντε χιλιομέτρων.","wiki_en":"Bahrain"},{"name":"Ομάν","emoji":"🇴🇲","meta":["Ασία","Μασκάτ","περίπου 4,5 εκατ."],"description":"Χώρα στα νοτιοανατολικά της Αραβικής Χερσονήσου, με ένα από τα πιο ποικίλα τοπία της περιοχής, από ερήμους μέχρι τα καταπράσινα βουνά Τζέμπελ Άχνταρ. Το Ομάν ήταν για αιώνες κέντρο του εμπορίου αρωματικών ρητινών, κυρίως του λιβανιού, που συλλέγεται ακόμη εδώ.","fact":"Το λιβάνι, που εξήγαγε το Ομάν για αιώνες σε όλον τον κόσμο, συλλέγεται ακόμη με τον παραδοσιακό τρόπο από δέντρα βοσβέλιας.","wiki_en":"Oman"},{"name":"Μιανμάρ","emoji":"🇲🇲","meta":["Ασία","Ναϊπιντάου","περίπου 54 εκατ."],"description":"Χώρα της Νοτιοανατολικής Ασίας, όπου στην πεδιάδα του Μπαγκάν στέκουν χιλιάδες βουδιστικοί ναοί και στούπες, χτισμένες στον Μεσαίωνα. Η χρυσή παγόδα Σουεντάγκον στη Ρανγκούν είναι ένα από τα πιο σεβαστά βουδιστικά μνημεία της περιοχής.","fact":"Η πρωτεύουσα της Μιανμάρ, η Ναϊπιντάου, χτίστηκε σχεδόν από το μηδέν και έγινε η κύρια πόλη της χώρας μόλις στα μέσα της δεκαετίας του 2000.","wiki_en":"Myanmar"},{"name":"Λάος","emoji":"🇱🇦","meta":["Ασία","Βιεντιάν","περίπου 7,5 εκατ."],"description":"Χώρα της Νοτιοανατολικής Ασίας χωρίς έξοδο στη θάλασσα, όπου οι βουδιστικοί ναοί του Λουάνγκ Πραμπάνγκ βρίσκονται κοντά στο οροπέδιο Μπολαβέν και στη μυστηριώδη Πεδιάδα των Πιθαριών. Η πρωινή προσφορά στους μοναχούς είναι από τις πιο γνωστές παραδόσεις της.","fact":"Η προέλευση των χιλιάδων πέτρινων πιθαριών στην Πεδιάδα των Πιθαριών, ηλικίας χιλιάδων ετών, δεν έχει εξηγηθεί πλήρως.","wiki_en":"Laos"},{"name":"Μπουτάν","emoji":"🇧🇹","meta":["Ασία","Θίμφου","περίπου 780 χιλ."],"description":"Βασίλειο των Ιμαλαΐων, γνωστό γιατί μετρά την επιτυχία του όχι μόνο με το ακαθάριστο εγχώριο προϊόν, αλλά και με έναν δείκτη «ακαθάριστης εθνικής ευτυχίας». Το μοναστήρι Τακτσάνγκ, κολλημένο σε κατακόρυφο βράχο, είναι από τους πιο αναγνωρίσιμους βουδιστικούς ναούς.","fact":"Η τηλεόραση επιτράπηκε επίσημα στο Μπουτάν μόλις στα τέλη της δεκαετίας του 1990, από τις τελευταίες χώρες στον κόσμο.","wiki_en":"Bhutan"},{"name":"Ουγκάντα","emoji":"🇺🇬","meta":["Αφρική","Καμπάλα","περίπου 47 εκατ."],"description":"Χώρα της Ανατολικής Αφρικής, που ο Ουίνστον Τσόρτσιλ αποκάλεσε «μαργαριτάρι της Αφρικής» για την ποικιλία των τοπίων της, από τις πηγές του Νείλου μέχρι ορεινά δάση όπου ζουν γορίλες. Τα πάρκα της είναι από τα λίγα μέρη στον κόσμο όπου βλέπεις γορίλες στη φύση.","fact":"Μέρος της Βικτόριας, της μεγαλύτερης λίμνης της Αφρικής, ανήκει στην Ουγκάντα, και ο Νείλος που βγαίνει από αυτήν ξεκινά εδώ.","wiki_en":"Uganda"},{"name":"Αλγερία","emoji":"🇩🇿","meta":["Αφρική","Αλγέρι","περίπου 45 εκατ."],"description":"Η μεγαλύτερη σε έκταση χώρα της Αφρικής, με τη Σαχάρα να καταλαμβάνει το μεγαλύτερο μέρος της, με αμμόλοφους και βραχογραφίες χιλιάδων ετών. Στον βορρά σώζονται τα εντυπωσιακά ερείπια της ρωμαϊκής πόλης Τίμγκαντ.","fact":"Οι βραχογραφίες στο οροπέδιο Τασίλι ν' Ατζέρ της Αλγερίας, ηλικίας χιλιάδων ετών, ανήκουν στην παγκόσμια κληρονομιά της UNESCO.","wiki_en":"Algeria"},{"name":"Λιβύη","emoji":"🇱🇾","meta":["Αφρική","Τρίπολη","περίπου 7 εκατ."],"description":"Χώρα στη μεσογειακή ακτή της Βόρειας Αφρικής, με τη Σαχάρα να καλύπτει το μεγαλύτερο μέρος του εδάφους της. Τα ερείπια των αρχαίων πόλεων Λέπτις Μάγκνα και Σαμπράθα είναι από τα καλύτερα διατηρημένα ρωμαϊκά μνημεία στην αφρικανική ήπειρο.","fact":"Η Λέπτις Μάγκνα, κάποτε από τις μεγαλύτερες ρωμαϊκές πόλεις της Αφρικής, εντυπωσιάζει ακόμη με τη διατήρηση των κτισμάτων της.","wiki_en":"Libya"},{"name":"Σουδάν","emoji":"🇸🇩","meta":["Αφρική","Χαρτούμ","περίπου 46 εκατ."],"description":"Χώρα στη βορειοανατολική Αφρική, όπου ο Λευκός και ο Γαλάζιος Νείλος ενώνονται σε ένα ποτάμι στο Χαρτούμ. Στο έδαφος του Σουδάν βρίσκονται περισσότερες πυραμίδες από ό,τι στην Αίγυπτο: τις έχτισαν οι ηγεμόνες του αρχαίου βασιλείου του Κους.","fact":"Οι νουβιανοί ηγεμόνες του Κους, πριν από τρεις χιλιάδες χρόνια περίπου, υπέταξαν και την Αίγυπτο, αποτελώντας μία από τις δυναστείες της.","wiki_en":"Sudan"},{"name":"Γκάνα","emoji":"🇬🇭","meta":["Αφρική","Άκρα","περίπου 33 εκατ."],"description":"Χώρα της Δυτικής Αφρικής, που πήρε το όνομά της από μια μεσαιωνική αυτοκρατορία, παρότι το έδαφός της βρίσκεται νότια από τα ιστορικά εδάφη εκείνου του κράτους. Η Γκάνα είναι μεγάλος παραγωγός κακάο, και στις ακτές της σώζονται παλιά ευρωπαϊκά οχυρά του εμπορίου.","fact":"Το 1957 η Γκάνα έγινε η πρώτη χώρα της υποσαχάριας Αφρικής που απέκτησε ανεξαρτησία από την αποικιοκρατία.","wiki_en":"Ghana"},{"name":"Σενεγάλη","emoji":"🇸🇳","meta":["Αφρική","Ντακάρ","περίπου 18 εκατ."],"description":"Το δυτικότερο σημείο της ηπειρωτικής Αφρικής, όπου το Ντακάρ βλέπει προς τον Ατλαντικό Ωκεανό. Το νησί Γκορέ, στα ανοιχτά της σενεγαλέζικης ακτής, με τα παλιά του κτίσματα, είναι στον κατάλογο παγκόσμιας κληρονομιάς της UNESCO ως ιστορικό μνημείο.","fact":"Η Σενεγάλη φημίζεται για το λάαμπ, μια παραδοσιακή μορφή πάλης που γεμίζει τα γήπεδα με χιλιάδες θεατές.","wiki_en":"Senegal"},{"name":"Ζιμπάμπουε","emoji":"🇿🇼","meta":["Αφρική","Χαράρε","περίπου 16 εκατ."],"description":"Χώρα στη νότια Αφρική, που ονομάστηκε από την αρχαία πέτρινη πόλη Μεγάλο Ζιμπάμπουε, χτισμένη με προσεκτικά ταιριασμένους λίθους χωρίς κονίαμα. Στα σύνορα με τη Ζάμπια βρίσκονται οι καταρράκτες Βικτόρια, από τους μεγαλύτερους στον κόσμο σε πλάτος.","fact":"Στην τοπική γλώσσα οι καταρράκτες Βικτόρια λέγονται Μόσι-οα-Τούνια, «ο καπνός που βροντά».","wiki_en":"Zimbabwe"},{"name":"Ακτή Ελεφαντοστού","emoji":"🇨🇮","meta":["Αφρική","Γιαμουσούκρο","περίπου 29 εκατ."],"description":"Χώρα της Δυτικής Αφρικής, που το όνομά της λέει ακριβώς αυτό που εννοεί: έτσι ονόμασαν οι Ευρωπαίοι έμποροι αυτό το κομμάτι της ακτής. Το Αμπιτζάν, η μεγαλύτερη πόλη της, θεωρείται ένα από τα πιο δυναμικά οικονομικά κέντρα της περιοχής.","fact":"Η Ακτή Ελεφαντοστού είναι ο μεγαλύτερος παραγωγός κακάο στον κόσμο και καλύπτει σημαντικό μέρος της παγκόσμιας σοδειάς.","wiki_en":"Ivory Coast"}];
